#include <string>

using namespace std;

int main() {
  // Declare variables
  string filename, file_contents;

  // Get the name of the file to open from the user
  cout << "Enter the name of the file to open: ";
  cin >> filename;

  // Open the file in read mode
  ifstream file(filename);

  // Check if the file was successfully opened
  if (!file) {
    cerr << "Error opening file " << filename << endl;
    return 1;
  }

  // Read the contents of the file into a string
  file_contents = "";
  while (file.good()) {
    file_contents += file.get();
  }

  // Close the file
  file.close();

  // Print the contents of the file to the console
  cout << "File contents: " << endl;
  cout << file_contents << endl;

  // Ask the user if they want to edit the file
  bool edit = false;
  while (!edit) {
    cout << "Do you want to edit this file? (y/n): ";
    cin >> edit;
    if (edit == 'n') {
      return 0;
    } else if (edit == 'y') {
      break;
    } else {
      cerr << "Invalid input. Please enter y or n." << endl;
    }
  }

  // If the user wants to edit the file, prompt them for new contents
  string new_contents = "";
  while (true) {
    cout << "Enter the new contents of the file: ";
    cin >> new_contents;
    if (!new_contents.empty()) {
      break;
    } else {
      cerr << "Invalid input. Please enter a non-empty string." << endl;
    }
  }

  // Save the new contents to a new file with the same name as the original file
  ofstream new_file(filename);
  if (!new_file) {
    cerr << "Error opening file " << filename << endl;
    return 1;
  }
  new_file << new_contents;
  new_file.close();

  // Print a message indicating that the file was saved successfully
