The Go version of this code is:
```go
package main

import "fmt"

func largestSmallestIntegers(lst []int) (a int, b int, c int, d int) {
    if len(lst) == 0 {
        return nil, nil, nil, nil
    }

    allNegative := make([]int, 0, len(lst))
    allNonNegative := make([]int, 0, len(lst))

    for _, x := range lst {
        if x < 0 {
            allNegative = append(allNegative, x)
        } else {
            allNonNegative = append(allNonNegative, x)
        }
    }

    negativeEven := make([]int, 0, len(allNegative))
    negativeOdd := make([]int, 0, len(allNegative))
    nonNegativeEven := make([]int, 0, len(allNonNegative))
    nonNegativeOdd := make([]int, 0, len(allNonNegative))

    for _, x := range allNegative {
        if x%2 == 0 {
            negativeEven = append(negativeEven, x)
        } else {
            negativeOdd = append(negativeOdd, x)
        }
    }

    for _, x := range allNonNegative {
        if x%2 == 0 {
            nonNegativeEven = append(nonNegativeEven, x)
        } else {
            nonNegativeOdd = append(nonNegativeOdd, x)
        }
    }

    a = max(negativeEven)
    b = min(nonNegativeEven)
    c = max(negativeOdd)
    d = min(nonNegativeOdd)

    return a, b, c, d
}

func main() {
    lst := []int{2, -4, 1, 3, 5, 7}
    largestSmallestIntegers(lst)
}
```
Note that this code is equivalent to the Python code in terms of functionality, but it uses Go's built-in `sort.Slice` and `sort.Ints` functions to sort the slices instead of using Python's `sorted()` function. Additionally, the `fmt.Println` function is used to print the results instead of using Python's `print()` function.

