    // Get references to the dropdown selectors and the table element
    const selector1 = document.getElementById('selector1');
    const selector2 = document.getElementById('selector2');
    const selector3 = document.getElementById('selector3');
    const table = document.querySelector('table');

    // Add an event listener to the submit button that will handle the form submission
    const submitButton = document.querySelector('.submit');
    submitButton.addEventListener('click', (event) => {
      event.preventDefault();

      // Get the selected options from each dropdown selector
      const option1 = selector1.value;
      const option2 = selector2.value;
      const option3 = selector3.value;

      // Check if any of the options are selected
