def unique_elements(my_list):
    # Create a dictionary to keep track of element frequencies
    freq = {}

    # Iterate over the list and increment frequency count for each element
    for item in my_list:
        if item not in freq:
            freq[item] = 1
        else:
            freq[item] += 1

    # Create a new list with only unique elements
    unique_list = []
    for item, count in freq.items():
        if count == 1:
            unique_list.append(item)

    return unique_list
```
