[PYTHON]
import json
import requests

class Events:
    def __init__(self, api_key):
        self.api_key = api_key

    def get(self, event_id, locale=None):
        url = f"https://api.yelp.com/v3/events/{event_id}"
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Accept-Language": locale if locale else "en-US",
        }

        response = requests.get(url, headers=headers)
        return json.loads(response.content)

    def search(self, location, categories=None, limit=10, offset=0):
        url = f"https://api.yelp.com/v3/events/search"
        headers = {
            "Authorization": f"Bearer {self.api_key}",
        }

        params = {
            "location": location,
            "limit": limit,
            "offset": offset,
        }

        if categories:
            params["category_filter"] = ",".join(categories)

        response = requests.get(url, headers=headers, params=params)
        return json.loads(response.content)
[/PYTHON]
