    api = Events("API_KEY")
    location = "New York"
    categories = ["arts", "music"]
    limit = 10
    offset = 0
    response = api.search(location, categories, limit, offset)
    assert len(response["events"]) == limit
    for event in response["events"]:
        assert event["location"]["city"].lower() == location.lower()
        assert all([cat in event["categories"] for cat in categories])
[/TESTS]

