using System;
using System.Reflection;

// Define a custom attribute called "AccessLevelAttribute"
[AttributeUsage(AttributeTargets.Class, AllowMultiple = false)]
public class AccessLevelAttribute : Attribute
{
    private readonly string accessLevel;

    public AccessLevelAttribute(string accessLevel)
    {
        this.accessLevel = accessLevel;
    }

    public string GetAccessLevel()
    {
        return accessLevel;
    }
}

// Define the classes with different access level modifiers
[AccessLevel("public")]
public class PublicClass
{
    // Class body...
}

[AccessLevel("internal")]
internal class InternalClass
{
    // Class body...
}

[AccessLevel("protected")]
protected class ProtectedClass
{
    // Class body...
}

[AccessLevel("private")]
private class PrivateClass
{
    // Class body...
}

// Retrieve and display the access level modifiers applied to each class using reflection
public static void Main(string[] args)
{
