[C++]
// RandomForestRegressor.h
#pragma once
#include <vector>
#include <string>
#include <unordered_map>
#include <memory>

class RandomForestRegressor {
private:
    // Member variables
    int nEstimators_;
    std::vector<std::unique_ptr<DecisionTreeRegressor>> estimators_;
    std::unordered_map<int, double> featureImportances_;

public:
    // Constructor and destructor
    RandomForestRegressor(int nEstimators);
    ~RandomForestRegressor();

    // Methods
    void fit(const std::vector<std::vector<double>>& X, const std::vector<double>& y);
    double predict(const std::vector<double>& x) const;
};

// RandomForestRegressor.cpp
#include "RandomForestRegressor.h"
#include <cmath>
#include <random>
#include <algorithm>

RandomForestRegressor::RandomForestRegressor(int nEstimators) : nEstimators_(nEstimators) {
    estimators_.resize(nEstimators_);
}

RandomForestRegressor::~RandomForestRegressor() {}

void RandomForestRegressor::fit(const std::vector<std::vector<double>>& X, const std::vector<double>& y) {
    // Initialize the estimators with random subsets of features and targets
    for (int i = 0; i < nEstimators_; ++i) {
        int nFeatures = rand() % X.size();
        std::vector<int> featureIndices(nFeatures);
        for (int j = 0; j < nFeatures; ++j) {
            featureIndices[j] = rand() % X[0].size();
        }
        estimators_[i] = std::make_unique<DecisionTreeRegressor>();
        estimators_[i]->fit(X, y, featureIndices);
    }
}

double RandomForestRegressor::predict(const std::vector<double>& x) const {
    double prediction = 0;
    for (int i = 0; i < nEstimators_; ++i) {
        prediction += estimators_[i]->predict(x);
    }
    return prediction / nEstimators_;
}
