    foreach ($validationRules as $field => $rule) {
        if (isset($formData[$field]) && $formData[$field] !== '') {
            switch ($rule) {
                case 'integer':
                    if (!is_int($formData[$field])) {
                        $errors[$field] = sprintf('The %s field must be an integer.', $field);
                    }
                    break;
                case 'required':
                    if (empty($formData[$field])) {
                        $errors[$field] = sprintf('The %s field is required.', $field);
                    }
                    break;
                case 'min:n':
                    if (strlen($formData[$field]) < n) {
                        $errors[$field] = sprintf(
                            'The %s field must have a minimum length of %d characters.',
                            $field, n
                        );
                    }
                    break;
                case 'max:n':
                    if (strlen($formData[$field]) > n) {
                        $errors[$field] = sprintf(
                            'The %s field must have a maximum length of %d characters.',
                            $field, n
                        );
                    }
                    break;
                default:
