function identifyFrequency(arr) {
  // Initialize an object to store the frequency of each character
  let freq = {};

  // Iterate over the array and count the frequency of each character
  for (let i = 0; i < arr.length; i++) {
    let current = arr[i];
    if (typeof current === 'string') {
      for (let j = 0; j < current.length; j++) {
        const char = current[j];
        freq[char] = (freq[char] || 0) + 1;
      }
    } else if (typeof current === 'number' || typeof current === 'boolean') {
      const num = `${current}`.replace(/,/g, '');
      for (let j = 0; j < num.length; j++) {
        const char = num[j];
        freq[char] = (freq[char] || 0) + 1;
      }
    } else if (Array.isArray(current)) {
      // Recursively count the frequency of each character in nested arrays
      identifyFrequency(current);
    }
  }

  // Sort the output by frequency and alphabetical order
  const sortedFreq = Object.entries(freq).sort((a, b) => {
    if (a[1] !== b[1]) {
      return b[1] - a[1];
    } else {
      return a[0].localeCompare(b[0]);
    }
  });

  // Return the sorted frequency object
  return sortedFreq;
}

// Example usage:
