      discountRate: 0.05,
    },
    type2: {
      discountRate: 0.1,
    },
  },
};

function calculateFinalPrice(originalPrice, serviceCenter, serviceType) {
  let finalPrice = originalPrice;

  // Check if the selected service center and service type are in the discount rates object
  if (discountRates.serviceCenters[serviceCenter] && discountRates.serviceTypes[serviceType]) {
    // Calculate the discount rate based on the selected service center and service type
    const discountRate = discountRates.serviceCenters[serviceCenter].discountRate + discountRates.serviceTypes[serviceType].discountRate;

