Here is a possible implementation of the polling system for input devices in a game engine:
```
#include <iostream>
#include <windows.h>
#include <dinput.h>

// Function to poll the mouse for input
void PollMouseInput() {
    // Create a DirectInput device for the mouse
    IDirectInputDevice8* pMouse = NULL;
    hr = DirectInputCreate(NULL, DIRECTINPUT_VERSION, IID_IDirectInputDevice8, (LPVOID*)&pMouse, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to create mouse device" << std::endl;
        return;
    }

    // Set the data format for the mouse
    hr = pMouse->SetDataFormat(&c_dfDIMouse);
    if (FAILED(hr)) {
        std::cout << "Failed to set data format for mouse" << std::endl;
        return;
    }

    // Acquire the mouse device
    hr = pMouse->Acquire();
    if (FAILED(hr)) {
        std::cout << "Failed to acquire mouse device" << std::endl;
        return;
    }

    // Poll the mouse for input
    DIDEVICEOBJECTDATA data[8];  // Array to hold the data from the mouse
    DWORD numData = sizeof(data) / sizeof(data[0]);  // Number of elements in the array
    hr = pMouse->GetDeviceData(sizeof(DIDEVICEOBJECTDATA), data, &numData, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to poll mouse for input" << std::endl;
        return;
    }

    // Handle the input data from the mouse
    for (DWORD i = 0; i < numData; i++) {
        switch (data[i].dwOfs) {
            case DIMOFS_X:
                std::cout << "Mouse X: " << data[i].dwData << std::endl;
                break;
            case DIMOFS_Y:
                std::cout << "Mouse Y: " << data[i].dwData << std::endl;
                break;
            default:
                std::cout << "Unknown mouse input" << std::endl;
                break;
        }
    }
}

// Function to poll the gamepads for input
void PollGamepadInput() {
    // Create a DirectInput device for each gamepad
    IDirectInputDevice8* pGamepad1 = NULL;
    hr = DirectInputCreate(NULL, DIRECTINPUT_VERSION, IID_IDirectInputDevice8, (LPVOID*)&pGamepad1, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to create gamepad 1 device" << std::endl;
        return;
    }

    IDirectInputDevice8* pGamepad2 = NULL;
    hr = DirectInputCreate(NULL, DIRECTINPUT_VERSION, IID_IDirectInputDevice8, (LPVOID*)&pGamepad2, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to create gamepad 2 device" << std::endl;
        return;
    }

    // Set the data format for each gamepad
    hr = pGamepad1->SetDataFormat(&c_dfDIJoystick);
    if (FAILED(hr)) {
        std::cout << "Failed to set data format for gamepad 1" << std::endl;
        return;
    }

    hr = pGamepad2->SetDataFormat(&c_dfDIJoystick);
    if (FAILED(hr)) {
        std::cout << "Failed to set data format for gamepad 2" << std::endl;
        return;
    }

    // Acquire each gamepad device
    hr = pGamepad1->Acquire();
    if (FAILED(hr)) {
        std::cout << "Failed to acquire gamepad 1 device" << std::endl;
        return;
    }

    hr = pGamepad2->Acquire();
    if (FAILED(hr)) {
        std::cout << "Failed to acquire gamepad 2 device" << std::endl;
        return;
    }

    // Poll each gamepad for input
    DIDEVICEOBJECTDATA data[8];  // Array to hold the data from each gamepad
    DWORD numData = sizeof(data) / sizeof(data[0]);  // Number of elements in the array
    hr = pGamepad1->GetDeviceData(sizeof(DIDEVICEOBJECTDATA), data, &numData, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to poll gamepad 1 for input" << std::endl;
        return;
    }

    hr = pGamepad2->GetDeviceData(sizeof(DIDEVICEOBJECTDATA), data, &numData, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to poll gamepad 2 for input" << std::endl;
        return;
    }

    // Handle the input data from each gamepad
    for (DWORD i = 0; i < numData; i++) {
        switch (data[i].dwOfs) {
            case DIJOFS_BUTTON(0):
                std::cout << "Gamepad 1 button 0: " << data[i].dwData << std::endl;
                break;
            case DIJOFS_BUTTON(1):
                std::cout << "Gamepad 1 button 1: " << data[i].dwData << std::endl;
                break;
            case DIJOFS_BUTTON(2):
                std::cout << "Gamepad 1 button 2: " << data[i].dwData << std::endl;
                break;
            case DIJOFS_BUTTON(3):
                std::cout << "Gamepad 1 button 3: " << data[i].dwData << std::endl;
                break;
            default:
                std::cout << "Unknown gamepad 1 input" << std::endl;
                break;
        }
    }

    for (DWORD i = 0; i < numData; i++) {
        switch (data[i].dwOfs) {
            case DIJOFS_BUTTON(0):
                std::cout << "Gamepad 2 button 0: " << data[i].dwData << std::endl;
                break;
            case DIJOFS_BUTTON(1):
                std::cout << "Gamepad 2 button 1: " << data[i].dwData << std::endl;
                break;
            case DIJOFS_BUTTON(2):
                std::cout << "Gamepad 2 button 2: " << data[i].dwData << std::endl;
                break;
            case DIJOFS_BUTTON(3):
                std::cout << "Gamepad 2 button 3: " << data[i].dwData << std::endl;
                break;
            default:
                std::cout << "Unknown gamepad 2 input" << std::endl;
                break;
        }
    }
}

int main() {
    // Initialize DirectInput
    HRESULT hr = S_OK;
    IDirectInput8* pDI = NULL;
    hr = DirectInputCreate(NULL, DIRECTINPUT_VERSION, IID_IDirectInput8, (LPVOID*)&pDI, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to create DirectInput interface" << std::endl;
        return 0;
    }

    // Initialize the mouse and gamepad devices
    IDirectInputDevice8* pMouse = NULL;
    hr = pDI->CreateDevice(GUID_SysMouse, &pMouse, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to create mouse device" << std::endl;
        return 0;
    }

    IDirectInputDevice8* pGamepad1 = NULL;
    hr = pDI->CreateDevice(GUID_SysKeyboard, &pGamepad1, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to create gamepad 1 device" << std::endl;
        return 0;
    }

    IDirectInputDevice8* pGamepad2 = NULL;
    hr = pDI->CreateDevice(GUID_SysKeyboard, &pGamepad2, NULL);
    if (FAILED(hr)) {
        std::cout << "Failed to create gamepad 2 device" << std::endl;
        return 0;
    }

    // Poll each device for input
    while (true) {
        PollDevice(pMouse);
        PollDevice(pGamepad1);
        PollDevice(pGamepad2);
    }

    return 0;
}
```

