def move_two_balls(arr):
    if len(arr) == 0:
        return True

    # Sort the array in non-decreasing order
    arr.sort()

    # Keep track of the number of swaps and right shift operations
    num_swaps = 0
    num_right_shifts = 0

    while num_swaps < 2 and num_right_shifts < len(arr):
        # Perform right shift operation
        arr.append(arr[0])
        arr.pop(0)
        num_right_shifts += 1

        # Swap exactly two elements in the array up to two times
        for i in range(len(arr) - 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                num_swaps += 1

    # Check if the final array is sorted in non-decreasing order
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False

    # Ensure the shifted array contains an even number of elements smaller than the first element
    count = 0
    for i in range(len(arr)):
        if arr[i] < arr[0]:
            count += 1
    if count % 2 == 1:
        return False

    return True

