```
import java.util.Scanner;

public class StringProcessor {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    System.out.print("Enter a string: ");
    String input = scanner.nextLine();

    // Remove all whitespace characters from the input string
    input = input.replaceAll("\\s+", "");

    int uppercaseCount = 0;
    int lowercaseCount = 0;
    int digitCount = 0;
    int specialCharacterCount = 0;

    // Count the number of each type of character in the input string
    for (int i = 0; i < input.length(); i++) {
      char c = input.charAt(i);
      if (Character.isUpperCase(c)) {
        uppercaseCount++;
      } else if (Character.isLowerCase(c)) {
        lowercaseCount++;
      } else if (Character.isDigit(c)) {
        digitCount++;
      } else {
        specialCharacterCount++;
      }
    }

    System.out.println("Uppercase letters: " + uppercaseCount);
    System.out.println("Lowercase letters: " + lowercaseCount);
    System.out.println("Digits: " + digitCount);
    System.out.println("Special characters: " + specialCharacterCount);
  }
}
```
This program uses a `Scanner` to read input from the user, and then removes all whitespace characters from the input string using the `replaceAll()` method. It then loops through each character in the input string and increments the appropriate counter based on its type (uppercase letter, lowercase letter, digit, or special character). Finally, it prints out the counts for each type of character.

```
import java.util.Scanner;

public class RepeatChar {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Get the character to be repeated
        System.out.print("Enter a printable ASCII character: ");
        char ch = sc.next().charAt(0);

        // Get the number of repetitions
        System.out.print("Enter the number of repetitions (between 3 and 10): ");
        int n = sc.nextInt();

        // Check if the number of repetitions is valid
        if (n < 3 || n > 10) {
            System.out.println("Invalid number of repetitions");
            return;
        }

        // Build the string
        String str = "";
        for (int i = 0; i < n; i++) {
            str += ch;
        }

        // Display the resulting string and its length
        System.out.println("Resulting string: " + str);
        System.out.println("Length of resulting string: " + str.length());

        // Calculate the sum of ASCII values of all characters in the string
        int asciiSum = 0;
        for (char c : str.toCharArray()) {
            asciiSum += (int) c;
        }
        System.out.println("Sum of ASCII values: " + asciiSum);
    }
}
