def calculate_earnings(stock_prices):
    earnings = 0
    for i in range(len(stock_prices) - 1):
        if stock_prices[i + 1] > stock_prices[i]:
            earnings += (stock_prices[i + 1] - stock_prices[i])
    return earnings

