import turtle

class Snake:
    def __init__(self):
        self.position = (0, 0)
        self.speed = 10
        self.segments = []

    def move(self):
        # Move the snake forward in the current direction
        if self.direction == 'up':
            self.position = (self.position[0], self.position[1] + self.speed)
        elif self.direction == 'down':
            self.position = (self.position[0], self.position[1] - self.speed)
        elif self.direction == 'left':
            self.position = (self.position[0] - self.speed, self.position[1])
        elif self.direction == 'right':
            self.position = (self.position[0] + self.speed, self.position[1])

    def up(self):
        # Change the snake's direction to up
        self.direction = 'up'

    def down(self):
        # Change the snake's direction to down
        self.direction = 'down'

    def left(self):
        # Change the snake's direction to the left
        self.direction = 'left'

    def right(self):
        # Change the snake's direction to the right
        self.direction = 'right'

class Food:
    def __init__(self):
        self.position = (0, 0)
        self.appearance = turtle.Turtle()
        self.appearance.shape('circle')
        self.appearance.color('red')
        self.appearance.penup()
        self.appearance.goto(self.position[0], self.position[1])

    def refresh(self):
        # Move the food to a new random position on the screen
        self.position = (random.randint(-250, 250), random.randint(-250, 250))
        self.appearance.goto(self.position[0], self.position[1])

class Score:
    def __init__(self):
        self.score = 0

    def increase(self, amount):
        # Increase the score by a specified amount
        self.score += amount

    def reset(self):
        # Reset the score to zero
        self.score = 0

# Main game loop
while True:
    # Move the snake forward in the current direction
    snake.move()

    # Check for collisions with the food
    if snake.position == food.position:
        # If the snake has eaten the food, increase the score and move the food to a new random position on the screen
        score.increase(10)
        food.refresh()

    # Check for collisions with the screen boundaries
    if (snake.position[0] < -250 or snake.position[0] > 250 or
            snake.position[1] < -250 or snake.position[1] > 250):
        # If the snake has hit a boundary, reset the score and start a new game
        score.reset()
        break

    # Check for collisions with the snake's own body
    for segment in snake.segments:
        if segment == snake.position:
            # If the snake has hit its own body, reset the score and start a new game
            score.reset()
            break

    # Handle user input to change the snake's direction
    if turtle.listen():
        keys = turtle.getkeys()
        for key in keys:
            if key == 'w':
                snake.up()
            elif key == 'a':
                snake.left()
            elif key == 's':
                snake.down()
            elif key == 'd':
                snake.right()

    # Update the game environment and display the score
    turtle.update()
    print(f'Score: {score.score}')
```

