/*
 * This function takes in a list of numbers as input, sorts them, and returns the median value.
 * If the length of the list is odd, the median is the middle element.
 * If the length of the list is even, the median is the average of the two middle elements.
 */
function getMedian(list) {
  // Sort the input list in ascending order
  list.sort((a, b) => a - b);

  // Get the length of the sorted list
  const len = list.length;

  // If the length of the list is odd, return the middle element
  if (len % 2 !== 0) {
    return list[Math.floor(len / 2)];
  }

  // If the length of the list is even, return the average of the two middle elements
  const mid1 = Math.floor(len / 2);
  const mid2 = Math.ceil(len / 2);
  return (list[mid1] + list[mid2]) / 2;
}
