```
#include <iostream>
#include <cstdlib>
#include <ctime>

using namespace std;

int main() {
    // Prompt user to input their choice
    cout << "Enter your choice (rock, paper, or scissors): ";
    string user_choice;
    cin >> user_choice;

    // Convert the user's choice to lowercase for comparison with computer choice
    transform(user_choice.begin(), user_choice.end(), user_choice.begin(), ::tolower);

    // Generate a random choice for the computer
    srand(time(0));
    int computer_choice = rand() % 3;

    // Compare the user's and computer's choices to determine the winner
    if (user_choice == "rock" && computer_choice == 2) {
        cout << "User wins!" << endl;
    } else if (user_choice == "scissors" && computer_choice == 0) {
        cout << "User wins!" << endl;
    } else if (user_choice == "paper" && computer_choice == 1) {
        cout << "User wins!" << endl;
    } else if (user_choice == "rock" && computer_choice == 0) {
        cout << "Computer wins!" << endl;
    } else if (user_choice == "scissors" && computer_choice == 1) {
        cout << "Computer wins!" << endl;
    } else if (user_choice == "paper" && computer_choice == 2) {
        cout << "Computer wins!" << endl;
    } else {
        cout << "Tie!" << endl;
    }

    // Display the user's choice, the computer's choice, and the outcome of the game
    cout << "Your choice: " << user_choice << endl;
    cout << "Computer's choice: ";
    if (computer_choice == 0) {
        cout << "rock" << endl;
    } else if (computer_choice == 1) {
        cout << "paper" << endl;
    } else {
        cout << "scissors" << endl;
    }

    // Wait for the user to press a key before exiting
    cout << "Press any key to continue...";
    cin.ignore(numeric_limits<streamsize>::max(), '\n');

    return 0;
}
```
This program uses the `rand()` function from `<cstdlib>` to generate a random number between 0 and 2, which is used as the computer's choice in the game. The user's input is converted to lowercase using the `transform` function from `<algorithm>`, and then compared with the computer's choice based on the rules of the game. If the user wins, the program displays a message indicating that they have won. If the computer wins, the program displays a message indicating that they have lost. If it is a tie, the program displays a message indicating that there is no winner. The program also waits for the user to press a key before exiting to allow the user to view the result.

