from flask import Flask, jsonify
import sqlite3

app = Flask(__name__)

# Connect to the database
conn = sqlite3.connect('data.db')
cur = conn.cursor()

@app.route('/users', methods=['GET'])
def get_users():
    cur.execute("SELECT * FROM users")
    rows = cur.fetchall()
    return jsonify(rows)

@app.route('/users/<id>', methods=['GET'])
def get_user(id):
    cur.execute("SELECT * FROM users WHERE id = ?", [id])
    row = cur.fetchone()
    if row is None:
        return jsonify({"error": "User not found"}), 404
    else:
        return jsonify(row)

@app.route('/users', methods=['POST'])
def create_user():
    # Insert user into the database
    cur.execute("INSERT INTO users (name, email, password) VALUES (?, ?, ?)", [request.form['name'], request.form['email'], request.form['password']])
    conn.commit()
    return jsonify({"message": "User created successfully"}), 201

@app.route('/users/<id>', methods=['PUT'])
def update_user(id):
    # Update user in the database
    cur.execute("UPDATE users SET name = ?, email = ?, password = ? WHERE id = ?", [request.form['name'], request.form['email'], request.form['password'], id])
    conn.commit()
    return jsonify({"message": "User updated successfully"}), 200

@app.route('/users/<id>', methods=['DELETE'])
def delete_user(id):
    # Delete user from the database
    cur.execute("DELETE FROM users WHERE id = ?", [id])
    conn.commit()
    return jsonify({"message": "User deleted successfully"}), 204

if __name__ == '__main__':
    app.run(debug=True)
```
