public class ClosureExample {
  public static void main(String[] args) {
    // Create a closure that takes a string and a number of exclamation marks
    // as input, and returns a new function that concatenates the string with
    // that many exclamation marks.
    Closure<Function<String, String>> createClosure = (string, numExclamations) -> {
