    // concatenated with three exclamation marks.
    Closure<String>[] closures = new Closure[]{
      createClosure.apply("Hello", 3),
      createClosure.apply("World", 3)
    };

    // Invoke each closure in the array with "Java" as input, and store the results in an array.
    String[] results = new String[closures.length];
    for (int i = 0; i < closures.length; i++) {
      results[i] = closures[i].apply("Java");
    }

    // Print the results of each closure invocation.
