def median(l: list, cmp_func: callable):
    """Find the median of elements in the list 'l' without sorting it or using built-in functions.
    Handles tuples with even and odd number of elements, non-standard python objects, duplicates, non-numeric values, a wider variety of input and output types, and uses cmp_func for comparisons; includes exception handling.
    """
    # Check if the list is empty
    if not l:
        raise ValueError("List is empty.")

    # Check if the comparison function is valid
    if not callable(cmp_func):
        raise TypeError("Comparison function is not callable.")

    # Check if all elements in the list are numeric
    for element in l:
        try:
            cmp_func(element, element)
        except TypeError:
            raise ValueError("Non-numeric value in list.")

    # Find the middle index of the list
    mid = len(l) // 2

    # Handle even number of elements
    if len(l) % 2 == 0:
        return (cmp_func(l[mid - 1], l[mid]) + cmp_func(l[mid], l[mid + 1])) / 2

    # Handle odd number of elements
    return l[mid]

# Test the function with different inputs and outputs
