```
class Employee:
    def __init__(self, name: str, salary: int, experience: int = 0):
        self.name = name
        self.salary = salary
        self.experience = experience
        self.projects = []

    def add_project(self, project_name: str, duration: int, role: str):
        if project_name in self.projects:
            index = self.projects.index(project_name)
            self.projects[index][1] += duration
            self.projects[index][2] = role
        else:
            self.projects.append([project_name, duration, role])

    def get_total_experience(self):
        total_experience = 0
        for project in self.projects:
            total_experience += project[1]
        return total_experience

    def get_average_salary(self):
        if not self.projects:
            return 0
        return self.salary / len(self.projects)

    def get_project_names(self):
        return [project[0] for project in self.projects]

    def get_project_duration(self, project_name: str):
        if project_name not in self.projects:
            return -1
        return self.projects[self.projects.index(project_name)][1]

    def get_project_role(self, project_name: str):
        if project_name not in self.projects:
            return None
        return self.projects[self.projects.index(project_name)][2]
```
Note: The methods `get_total_experience`, `get_average_salary`, `get_project_names`, `get_project_duration`, and `get_project_role` are all public instance methods, meaning they can be called on an instance of the class without using any special syntax. The method `add_project` is a private instance method, meaning it can only be called from within the class itself or from another method that has been granted permission to do so through the use of the `@` symbol before the method name in the definition.

[PYTHON]
fn main() {
    let number = -15;
    println!("{}", get_prime_factors(number));
}

fn get_prime_factors(number: i32) -> Vec<i32> {
    if number <= 1 {
        return vec![];
    }

    let mut factors = vec![];

    for i in 2..number + 1 {
        if number % i == 0 {
            factors.push(i);
            number /= i;
            break;
        }
    }

    factors
}
[/PYTHON]
