def is_emirp(n):
    if not n.isdigit() or n < 0 or n % 2 == 0:
        return "Error: Input must be a valid positive integer"
    elif n == 1:
        return "Error: 1 is not an emirp number"
    else:
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return "Error: Input number is not prime"
        for j in range(2, n + 1):
            if n % j == 0 and (j - n) % 2 == 0:
                return "Error: Input number is not emirp"
        for k in range(2, int(n ** 0.5) + 1):
            if n % k == 0 and (k - n) % 2 == 0:
                return "Error: Input number's reverse is not prime"
        for l in range(2, int(n ** 0.5) + 1):
            if n % l == 0 and (l - n) % 2 == 0:
                return "Error: Input number is a palindrome"
        for m in range(2, int(n ** 0.5) + 1):
            if n % m == 0 and (m - n) % 2 == 0:
                return "Error: Input number's reverse squared is not prime"
        emirp_root = math.pi(n) * math.pi(n)
        return f"Input number is an emirp with emirp root {emirp_root}"
```

