function gcd(a, b) {
  // Check if either of the input values are negative
  if (a < 0 || b < 0) {
    throw new Error("Invalid input value");
  }

  // Initialize the divisor to 1
  let divisor = 1;

  // Loop until the divisor is greater than or equal to both a and b
  while (divisor <= Math.min(a, b)) {
    // Check if the current divisor divides both a and b without leaving a remainder
    if ((a % divisor === 0) && (b % divisor === 0)) {
      // If it does, return the current divisor as the GCD
      return divisor;
    }

    // Increment the divisor by 1 and loop again
    divisor++;
  }

  // If no common factor is found, return -1 to indicate that the inputs are not relatively prime
  return -1;
}
```
This code uses a while loop to iterate over the possible values of the divisor, starting from 1 and increasing by 1 until it finds a value that divides both `a` and `b` without leaving a remainder. If such a divisor is found, its value is returned as the GCD. Otherwise, -1 is returned to indicate that the inputs are not relatively prime.

The code also includes an error check to ensure that both input values are non-negative integers. This is necessary because the algorithm assumes that the inputs are positive integers, and it would return incorrect results if given negative or decimal numbers as input.

