import java.util.Scanner;
public class ReverseAndCombineStrings {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String string1 = sc.next();
        String string2 = sc.next();
        String string3 = sc.next();

        // Reverse the order of the characters in each string
        String reversedString1 = new StringBuilder(string1).reverse().toString();
        String reversedString2 = new StringBuilder(string2).reverse().toString();
        String reversedString3 = new StringBuilder(string3).reverse().toString();

        // Combine the reversed strings in reverse order
        String combinedString = reversedString3 + reversedString2 + reversedString1;

        // Remove any duplicate characters from the combined string
        Set<Character> uniqueChars = new HashSet<>();
        for (int i = 0; i < combinedString.length(); i++) {
            char currentChar = combinedString.charAt(i);
            if (!uniqueChars.contains(currentChar)) {
                uniqueChars.add(currentChar);
