def find_max_diff(arr, target):
    rows = len(arr)
    cols = len(arr[0])
    max_diff = 0
    count = 0
    for i in range(rows):
        for j in range(cols):
            if arr[i][j] == target:
                count += 1
            if count >= 2:
                break
        for k in range(cols-1, -1, -1):
            if arr[i][k] == target:
                count += 1
            if count >= 2:
                break
        if count >= 2:
            max_diff = max(max_diff, abs(arr[i][0] - arr[i][-1]))
    return max_diff, count
