// Function to convert a string to an integer
int strToInt(const string& str) {
  int result = 0;
  for (char c : str) {
    if (!isdigit(c)) {
      // If the character is not a digit, return 0
      return 0;
    }
    result = result * 10 + (c - '0');
  }
