string intToBinary(int num) {
  string binaryString = "";
  while (num > 0) {
    binaryString += (num % 2 == 1 ? "1" : "0");
    num /= 2;
  }
  return binaryString;
}

// Function to convert a binary string to an integer
int binaryToInt(const string& str) {
  int result = 0;
  for (int i = 0; i < str.size(); i++) {
    if (str[i] != '0' && str[i] != '1') {
      // If the character is not a binary digit, return 0
      return 0;
    }
    result += str[i] == '1' ? pow(2, i) : 0;
  }
  return result;
}

// Function to convert an integer to a hexadecimal string
string intToHex(int num) {
  string hexString = "";
  while (num > 0) {
    hexString += "0123456789abcdef"[num % 16];
    num /= 16;
  }
  return hexString;
}

