int hexToInt(const string& str) {
  int result = 0;
  for (int i = 0; i < str.size(); i++) {
    if (!isxdigit(str[i])) {
      // If the character is not a hex digit, return 0
      return 0;
    }
    result += str[i] == '0' ? pow(16, i) : 0;
  }
  return result;
}

