class UserPermissionAuthController(object):
    def authenticate(self, username, password):
        user = UserPermissionAuthFactory.create(username=username, password=password)
        if not user:
            return None
        return user

    def has_role(self, user, role):
        roles.has_role(user, role)

    def has_permission(self, user, permission):
        permissions.has_permission(user, permission)
```
