```
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.io.LongWritable;
import org.apache.hadoop.io.Text;
import org.apache.hadoop.mapreduce.Job;
import org.apache.hadoop.mapreduce.Mapper;
import org.apache.hadoop.mapreduce.Reducer;
import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;
import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;

public class WordCount {
  public static class TokenizerMapper extends Mapper<LongWritable, Text, Text, LongWritable> {
    private final static Text word = new Text();
    private final static LongWritable one = new LongWritable(1);

    public void map(LongWritable key, Text value, Context context) throws IOException, InterruptedException {
      StringTokenizer itr = new StringTokenizer(value.toString());
      while (itr.hasMoreTokens()) {
        word.set(itr.nextToken());
        context.write(word, one);
      }
    }
  }

  public static class IntSumReducer extends Reducer<Text, LongWritable, Text, LongWritable> {
    private final LongWritable result = new LongWritable();

    public void reduce(Text key, Iterator<LongWritable> values, Context context) throws IOException, InterruptedException {
      long sum = 0;
      while (values.hasNext()) {
        sum += values.next().get();
      }
      result.set(sum);
      context.write(key, result);
    }
  }

  public static void main(String[] args) throws Exception {
    Job job = new Job(new Configuration());
    FileInputFormat.addInputPath(job, new Path("/input/path"));
    FileOutputFormat.setOutputPath(job, new Path("/output/path"));
    job.setMapperClass(TokenizerMapper.class);
    job.setReducerClass(IntSumReducer.class);
    System.exit(job.waitForCompletion(true) ? 0 : 1);
  }
}
```
This program is a WordCount example that counts the number of occurrences of each word in a text file and outputs the results to a new file. It uses the `TokenizerMapper` class to split the input into individual words, and the `IntSumReducer` class to sum up the counts for each word. The `main()` method sets up the Hadoop job configuration and runs it.

