    List<Integer> fib = new ArrayList<>();
    fib.add(0);
    fib.add(1);

    // Iterate over the numbers in the fibonacci sequence
    for (int i = 2; i <= n; i++) {
      int previous = fib.get(i - 1);
      int previousPrevious = fib.get(i - 2);
