        int freq = 0; // frequency of each perfect square found
        int i, j;

        // loop from 1 to max
        for (i = 1; i <= max; i++) {
            // check if i is a perfect square
            for (j = 0; j < i; j++) {
                if (Math.sqrt(i) == (int) Math.sqrt(i)) {
                    count++; // increment counter for total perfect squares
                    freq++; // increment frequency of this perfect square
                    break; // break inner loop since we have found a perfect square
                }
            }
        }

        System.out.println("Total perfect squares: " + count);
        System.out.println("Frequency of each perfect square: " + freq);
    }
}
```
