use App\Models\Addon;
use Illuminate\Support\Facades\Gate;

function checkPermission(Addon $addon): bool
{
    $user = Auth::user();

    if ($user->user_type === 'admin') {
        return true;
    }

    $role = $user->staff->role;
    $permissions = $role->permissions;

