You can implement a rate limiter using a combination of a timer and a counter variable. The timer will track the time since the last request was made, and the counter will keep track of the number of requests made during that time. When the timer is triggered or the counter reaches the limit specified in `VK.config.sendLimit`, the rate limiter will fulfill the expectation (`exp.fulfill()`).
```swift
import Foundation

class RateLimiter {
    private let limit: Int
    private var executed = 0
    private var lastRequestTime: TimeInterval?

    init(limit: Int) {
        self.limit = limit
    }

    func execute(onSuccess: @escaping () -> Void, onError: @escaping (Error) -> Void) {
        let currentTime = Date().timeIntervalSince1970

        if let lastRequestTime = self.lastRequestTime {
            // Check if the time since the last request is less than the limit
            if currentTime - lastRequestTime < limit {
                executed += 1

                // If the counter has reached the limit, fulfill the expectation
                if executed >= limit {
                    exp.fulfill()
                }
            } else {
                self.lastRequestTime = currentTime
                executed = 1
            }
        } else {
            self.lastRequestTime = currentTime
            executed = 1
        }

        // Execute the success or error closure based on the API response
        if let data = data, let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 {
            onSuccess()
        } else {
            onError(error!)
        }
    }
}
```
To use the rate limiter in your API request handler, you can create an instance of `RateLimiter` and pass it as a parameter to the `execute` method. The `execute` method will take care of fulfilling the expectation when the limit is reached.
```swift
let rateLimiter = RateLimiter(limit: VK.config.sendLimit)

func handleAPIRequest(completionHandler: @escaping (Result<Data, Error>) -> Void) {
    // Create a request and set up the completion handler
    let url = URL(string: "https://api.vk.com/method/users.get")!
    var request = URLRequest(url: url)

    // Add the rate limiter to the request
    request.setValue("Bearer \(VK.config.accessToken)", forHTTPHeaderField: "Authorization")

    let task = session.dataTask(with: request) { data, response, error in
        // Execute the success or error closure based on the API response
        if let data = data, let httpResponse = response as? HTTPURLResponse, httpResponse.statusCode == 200 {
            completionHandler(.success(data))
        } else {
            completionHandler(.failure(error!))
        }
    }

    // Start the request and wait for the rate limiter to fulfill the expectation
    task.resume()
    rateLimiter.execute(onSuccess: {
        // The API request was successful, continue with the next step
    }, onError: { error in
        // The API request failed, handle the error and continue with the next step
    })
}
```
By using the `RateLimiter`, you can ensure that your API requests are made at a rate of no more than `VK.config.sendLimit` per second, which is the recommended limit for VKontakte's API.

Here's a more efficient version of the `is_prime` function that checks for primality using only odd numbers up to the square root of `n`:
```python
def is_prime(n):
    if n < 2:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True
```
