import re

def validate_input(input_string):
    """
    Validate the input string by checking if it matches the specified pattern.

    Args:
        input_string (str): The input string to be validated.

    Returns:
        bool: True if the input string is valid, False otherwise.
    """
    # Check if the input string is an empty string
    if not input_string:
        return False

    # Define the pattern for a valid input string
    pattern = r"^[A-Z]{2}[0-9]{1,3}$"

    # Use the re.match() function to check if the input string matches the pattern
    if re.match(pattern, input_string):
        return True
    else:
        return False

def main():
