        # Prompt the user for an input string
        input_string = input("Enter a 2-letter country code followed by 1 to 3 digits: ")

        # Validate the input string using the validate_input() function
        if validate_input(input_string):
            print(f"{input_string} is a valid input.")
        else:
            print(f"{input_string} is not a valid input. Please enter a 2-letter country code followed by 1 to 3 digits.")

if __name__ == "__main__":
    main()

