function hcf_bitwise(a, b) {
  // Initialize the result to be the maximum value
  let result = Math.max(a, b);

  // While the result is non-zero, continue to divide it by 2 and check if it divides both a and b evenly
  while (result > 0) {
    if ((a % result === 0) && (b % result === 0)) {
      return result;
    }

    // If the result does not divide both a and b evenly, try dividing it by 2
    result = result >>> 1;
  }

  // If no common factors were found, return 1
  return 1;
}
```
