Here is an example of how to encrypt and decrypt data in MongoDB using the AES-256 algorithm:
```
const crypto = require('crypto');

// Encrypt a string
function encrypt(data) {
  const cipher = crypto.createCipheriv('aes-256-cbc', 'your_secret_key_here', 'your_initialization_vector_here');
  let encrypted = cipher.update(data, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return encrypted;
}

// Decrypt an encrypted string
function decrypt(encrypted) {
  const decipher = crypto.createDecipheriv('aes-256-cbc', 'your_secret_key_here', 'your_initialization_vector_here');
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

// Example usage
const data = { _id: ObjectId("5934d2f06a57e14b9c1b3b76"), name: "John Doe", email: "johndoe@example.com" };

// Encrypt the data
const encryptedData = encrypt(JSON.stringify(data));

// Store the encrypted data in MongoDB
db.collection('users').insertOne({ _id: '5934d2f06a57e14b9c1b3b76', encryptedData });

// Retrieve the encrypted data from MongoDB
const user = db.collection('users').findOne({ _id: '5934d2f06a57e14b9c1b3b76' });

// Decrypt the data
const decryptedData = JSON.parse(decrypt(user.encryptedData));
```
