```python
def complex_prime_sort(l1: list, l2: list):
    """
    Gather a sorted list of even numbers which are simultaneously prime from two listed sets.
    >>> complex_prime_sort([-1, 2, -4, 5, 6], [5, 3, -5, 2, -3, 3, 8, 0, 14, 4, -10])
    [2, 2]
    """
    def merge_sort(m: list, n: list):
        # Merge sort implementation
        if len(m) == 0 or len(n) == 0:
            return m + n
        mid = len(m) // 2
        left = merge_sort(m[:mid], n[:mid])
        right = merge_sort(m[mid:], n[mid:])
        return list(chain.from_iterable(zip(left, right)))

    def prime_check(x: int):
        # Primality check implementation
        if x < 2:
            return False
        for i in range(2, int(x ** 0.5) + 1):
            if x % i == 0:
                return False
        return True

    list_prime_even = []

    for num1 in l1:
        if num1 % 2 == 0 and prime_check(num1):
            list_prime_even.append(num1)

    for num2 in l2:
        if num2 < 0:
            raise ValueError("Negative integer is not permitted")
        if num2 % 2 == 0 and prime_check(num2):
            list_prime_even.append(num2)

    return merge_sort(list_prime_even, [])
