```
public bool IsSorted(int[,] arr) {
    // Evaluate row-wise sorting
    for (int i = 0; i < arr.GetLength(0); i++) {
        int[] row = new int[arr.GetLength(1)];
        for (int j = 0; j < arr.GetLength(1); j++) {
            row[j] = arr[i, j];
        }
        if (!IsSorted(row)) {
            return false;
        }
    }

    // Evaluate column-wise sorting
    for (int j = 0; j < arr.GetLength(1); j++) {
        int[] col = new int[arr.GetLength(0)];
        for (int i = 0; i < arr.GetLength(0); i++) {
            col[i] = arr[i, j];
        }
        if (!IsSorted(col)) {
            return false;
        }
    }

    // If both row-wise and column-wise sorting are satisfied, return true
    return true;
}

public bool IsSorted(int[] arr) {
    for (int i = 0; i < arr.Length - 1; i++) {
        if (arr[i] > arr[i + 1]) {
            return false;
        }
    }
    return true;
}
```
