[PYTHON]
def get_stats(numbers):
    try:
        numbers = [int(n) for n in numbers if int(n) > 0 and int(n) <= 1000]
        if not numbers:
            raise ValueError("Invalid input")

        frequency = {}
        for num in numbers:
            if num not in frequency:
                frequency[num] = 1
            else:
                frequency[num] += 1

        sorted_frequency = sorted(frequency.items(), key=lambda x: x[0])

        mode = []
        previous = None
        current_count = 0
        for num, count in sorted_frequency:
            if num == previous:
                current_count += count
            else:
                if previous is not None:
                    mode.append((previous, current_count))
                previous = num
                current_count = count
        if previous is not None:
            mode.append((previous, current_count))

        mean = sum(numbers) / len(numbers)
        median = sorted(numbers)[len(numbers) // 2] if len(numbers) % 2 == 0 else sum(sorted(numbers)[len(numbers) // 2 - 1:len(numbers) // 2 + 1]) / 2

        return "Mean: {:.2f}\nMedian: {}\nMode: {}".format(mean, median, str(mode) if mode else None)
    except ValueError:
        return "Invalid input"
