```python
class MyDataStructure:
    def __init__(self):
        self.data = {}

    # O(1) insertion, O(n) lookup, O(1) deletion, O(1) key existence check
    def insert(self, key, value):
        self.data[key] = value

    # O(1) retrieval, O(1) key existence check
    def get(self, key):
        return self.data[key] if key in self.data else None

    # O(1) deletion, O(1) key existence check
    def delete(self, key):
        value = self.data.pop(key, None)
        return value

    # O(nlogn) sorting, O(n) retrieval, O(1) space complexity
    def get_all_keys(self):
        keys = list(self.data.keys())
        keys.sort()
        return keys

    # O(1) number of elements retrieval, O(1) space complexity
    def size(self):
        return len(self.data)

    # O(n) maximum value search, O(1) space complexity
    def get_max_value(self):
        max_key = None
        max_value = -float('inf')
        for key, value in self.data.items():
            if value > max_value:
                max_key = key
                max_value = value
        return max_key, max_value

    # O(n) minimum value search, O(1) space complexity
    def get_min_value(self):
        min_key = None
        min_value = float('inf')
        for key, value in self.data.items():
            if value < min_value:
                min_key = key
                min_value = value
        return min_key, min_value

    # O(n) average value calculation, O(1) space complexity
    def get_average_value(self):
        sum = 0
        for key, value in self.data.items():
            sum += value
        return sum / len(self.data)

    # O(n) sum calculation, O(1) space complexity
    def get_sum(self):
        sum = 0
        for key, value in self.data.items():
            sum += value
        return sum
```
