# Create a list to store the fruits
fruits = []

# Prompt the user to enter 20 unique fruit names
for i in range(20):
    fruit_name = input("Enter a fruit name: ")
    if fruit_name in fruits:
        print("Duplicate fruit name found. Please try again.")
        continue
    else:
        fruits.append(fruit_name)

# Sort the list of fruits in alphabetical order using merge sort
def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    while len(left) > 0 and len(right) > 0:
        if left[0] <= right[0]:
            result.append(left.pop(0))
        else:
            result.append(right.pop(0))
    if len(left) > 0:
        result += left
    if len(right) > 0:
        result += right
    return result

# Sort the list of fruits in reverse order using the merge sort algorithm
fruits = merge_sort(fruits)
fruits.reverse()

# Count the number of vowels in each fruit name using a function with time complexity O(n)
def count_vowels(fruit):
    count = 0
    for char in fruit:
        if char in "aeiouAEIOU":
            count += 1
    return count

# Display the fruit names along with their corresponding vowel counts
for fruit, vowel_count in zip(fruits, [count_vowels(fruit) for fruit in fruits]):
    print(f"{fruit} - {vowel_count}")
```

