public class FibonacciSequence {
    public static void main(String[] args) {
        int n = 1_000_000; // 1 million
        int a = 0, b = 1;
        System.out.print("0, 1, ");
        for (int i = 2; i <= n; i++) {
            int c = a + b;
            a = b;
            b = c;
            System.out.print(c + ", ");
        }
    }
}
```
