// Serialization process
void Serialize(BinaryWriter bw)
{
    // Write activate event ID
    bw.Write(m_activateEventId);

    // Write 0 as a placeholder for the unsigned integer
    bw.Write((uint)0);

    // Write attachment string pointer using custom method
    s.WriteStringPointer(bw, m_attachment);
}

// Deserialization process
void Deserialize(BinaryReader br)
{
    // Read activate event ID
