[PYTHON]
def is_palindrome(string):
    # Convert the string to lowercase
    string = string.lower()

    # Create an empty dictionary to store the character counts
    char_counts = {}

    # Loop through each character in the string
    for char in string:
        # Check if the character is already in the dictionary
        if char in char_counts:
            # If it is, increment its count
            char_counts[char] += 1
        else:
            # If it's not, add it to the dictionary with a count of 1
            char_counts[char] = 1

    # Check if the string is a palindrome
    is_palindrome = True
    for i in range(len(string) // 2):
        if string[i] != string[-i - 1]:
            is_palindrome = False
            break

    # If the string is a palindrome with even character counts, return the character counts
    if is_palindrome and len(string) % 2 == 0:
        return char_counts

    # If the string is a palindrome with odd character counts, return the character counts with the center character removed
    if is_palindrome and len(string) % 2 == 1:
        char_counts.pop(string[len(string) // 2], None)
        return char_counts

    # If the string is not a palindrome, return False
    return False
[/PYTHON]
