```
#include <Wire.h> // I2C communication library
#include <Adafruit_SSD1306.h> // OLED display library

// Pin definitions for the gas sensor
const int gasSensorPin = A5;

// Pin definitions for the microcontroller
const int buttonPin = 2;
const int ledPin = 13;

// Create an instance of the OLED display class
Adafruit_SSD1306 display = Adafruit_SSD1306(OLED_RESET);

void setup() {
  // Initialize the gas sensor pin as an input
  pinMode(gasSensorPin, INPUT);

  // Initialize the button pin as an input with pull-up resistor
  pinMode(buttonPin, INPUT_PULLUP);

  // Initialize the LED pin as an output
  pinMode(ledPin, OUTPUT);

  // Initialize the OLED display
