  // Clear the display buffer
  display.clearDisplay();
}

void loop() {
  // Read the value from the gas sensor
  int gasValue = analogRead(gasSensorPin);

  // If the button is pressed, turn on the LED and play a note
  if (digitalRead(buttonPin) == LOW) {
    digitalWrite(ledPin, HIGH);
    tone(8, 440, 500);
  } else {
    // If the button is not pressed, turn off the LED and stop playing the note
    digitalWrite(ledPin, LOW);
    noTone(8);
  }

  // Update the display with the gas value
  display.clearDisplay();
  display.setTextSize(2);
  display.setCursor(0, 0);
  display.print("Gas Value: ");
