double calculateMedian(const std::vector<int>& nums) {
    // Calculate the median of the vector
    int mid = nums.size() / 2;
    if (nums.size() % 2 == 0) {
        return (nums[mid - 1] + nums[mid]) / 2.0;
    } else {
        return nums[mid];
    }
