```
import java.util.*;

public class LongestString {
    public static void main(String[] args) {
        // Create a list of strings to sort and find the longest one
        List<String> strings = new ArrayList<>();
        strings.add("hello");
        strings.add("world");
        strings.add("abcdefg");
        strings.add("1234567890");
        strings.add("!@#$%^&*()_+-=[]{}|;':\"<>,./?`~");

        // Sort the list of strings based on their lengths
        sortByLength(strings);

        // Print the longest string
        System.out.println("Longest string: " + findLongestString(strings));
    }

    public static void sortByLength(List<String> strings) {
        // Custom sorting algorithm to sort the list of strings by their lengths
        for (int i = 0; i < strings.size(); i++) {
            for (int j = i + 1; j < strings.size(); j++) {
                if (strings.get(i).length() > strings.get(j).length()) {
                    String temp = strings.get(i);
                    strings.set(i, strings.get(j));
                    strings.set(j, temp);
                }
            }
        }
    }

    public static String findLongestString(List<String> strings) {
        // Find the longest string in the sorted list of strings
        int longestIndex = 0;
        for (int i = 1; i < strings.size(); i++) {
            if (strings.get(i).length() > strings.get(longestIndex).length()) {
                longestIndex = i;
            }
        }
        return strings.get(longestIndex);
    }
}
