def url_check(url_name):
    if len(url_name) < 10 or len(url_name) > 100:
        return 'Invalid'
    if not url_name.startswith('http://') and not url_name.startswith('https://'):
        return 'Invalid'
    if url_name.count('/') > 2:
        return 'Invalid'
    if not url_name.endswith('.com') and not url_name.endswith('.org') and not url_name.endswith('.edu') and not url_name.endswith('.gov') and not url_name.endswith('.net') and not url_name.endswith('.io'):
        return 'Invalid'
    if url_name.count('#') > 3:
        return 'Invalid'
    if not any(c.isalnum() or c == '-' or c == '_' for c in url_name):
        return 'Invalid'
    if not any(c.isalpha() and c != '-' for c in url_name[:url_name.find('.')]):
        return 'Invalid'
    return 'Valid'

