    // Generate a random number within the range of perfect cubes
    int num = (int)(Math.random() * 10 + 1);
    System.out.println("The generated number is: " + num);

    // Calculate the cube of the number
    int cube = num * num * num;
    System.out.println("The cube of the number is: " + cube);

    // Check if the cube is equal to the original number
    if (cube == num) {
