fn get_least_significant_even_number(numbers: &[i32]) -> Result<i32, &str> {
    let mut least_significant_digit = 10;
    let mut even_number = None;

    for number in numbers {
        if number % 2 == 0 {
            let binary_representation = number.to_string(2);
            let last_digit = binary_representation.parse::<i32>().unwrap();

            if last_digit < least_significant_digit {
                least_significant_digit = last_digit;
                even_number = Some(number);
            }
        }
    }

    match even_number {
        Some(number) => Ok(number),
        None => Err("No even numbers found in the array"),
    }
}
