function validateEmail(email) {
  const pattern = /\w+@\w+\.\w+/; // regex pattern for validating emails
  let match = kmp(email, pattern); // use KMP algorithm to find all occurrences of the pattern in the email
  if (match !== null && match.length > 0) {
    const domain = match[0].split("@")[1]; // get the domain part of the email address
    const tlds = ["com", "net", "org"]; // whitelist of valid TLDs
