public static String[] transformString(String input) {
    // Check if the input string is valid
    if (input == null || input.length() < 10 || !input.matches("[a-z]*")) {
        throw new IllegalArgumentException("Invalid input string");
    }

    // Split the input string into an array of substrings with length 4
    String[] substrings = input.split("(?<=\\G..)");

    // Create a set to store the unique elements
    Set<String> uniqueElements = new HashSet<>();

    // Loop through the substrings and add each element to the set
    for (String substring : substrings) {
        uniqueElements.add(substring);
    }

    // Convert the set to an array in alphabetical order
    String[] output = uniqueElements.toArray(new String[0]);
    Arrays.sort(output);

    return output;
}

