from abc import ABC, abstractmethod

class Animal(ABC):
    def __init__(self, name, age, health):
        self._name = name
        self._age = age
        self._health = health

    @abstractmethod
    def communicate(self):
        pass

    @abstractmethod
    def display_behavior(self):
        pass

    def get_name(self):
        return self._name

    def set_name(self, name):
        self._name = name

    def get_age(self):
        return self._age

    def set_age(self, age):
        self._age = age

    def get_health(self):
        return self._health

    def set_health(self, health):
        self._health = health

class Cat(Animal):
    def communicate(self):
        return "Meow!"

    def display_behavior(self):
        return "Lap-lap"

class Dog(Animal):
    def communicate(self):
        return "Woof woof!"

    def display_behavior(self):
        return "Bark-bark"

class Parrot(Animal):
    def communicate(self):
        return "Squawk!"

    def display_behavior(self):
        return "Fly-fly"

class Elephant(Animal):
    def communicate(self):
        return "Trumpet-trumpet-trumpet!"

    def display_behavior(self):
        return "Walk-walk-walk"

