```
public class AdventureGame
{
    private readonly Player _player;
    private readonly List<Scenario> _scenarios = new List<Scenario>();
    private int _currentScenarioIndex;

    public AdventureGame(Player player)
    {
        _player = player;
        _currentScenarioIndex = 0;
    }

    public void StartGame()
    {
        Console.WriteLine("Welcome to the text-based adventure game!");
        Console.WriteLine();
        DisplayCurrentScenario();
    }

    private void DisplayCurrentScenario()
    {
        var scenario = _scenarios[_currentScenarioIndex];
        Console.WriteLine(scenario.Description);
        for (int i = 0; i < scenario.Choices.Count; i++)
        {
            Console.WriteLine($"{i + 1}. {scenario.Choices[i].Text}");
        }
    }

    public void MakeChoice(int choiceNumber)
    {
        var scenario = _scenarios[_currentScenarioIndex];
        var choice = scenario.Choices[choiceNumber - 1];

        switch (choice.Action)
        {
            case ActionType.HealthIncrease:
                _player.Health += 20;
                break;
            case ActionType.StrengthIncrease:
                _player.Strength += 5;
                break;
            case ActionType.AgilityIncrease:
                _player.Agility += 3;
                break;
        }

        Console.WriteLine($"You made the choice {choice.Text}.");
        Console.WriteLine();

        if (++_currentScenarioIndex < _scenarios.Count)
        {
            DisplayCurrentScenario();
        }
    }

    public bool IsGameOver()
    {
        return _currentScenarioIndex >= _scenarios.Count;
    }

    public int GetOutcome()
    {
        var outcome = 0;
        if (_player.Health <= 0)
        {
            outcome = -1; // game over
        }
        else if (_currentScenarioIndex == _scenarios.Count - 1)
        {
            outcome = 1; // victory
        }
        return outcome;
    }
}

public class Player
{
    public int Health { get; set; }
    public int Strength { get; set; }
    public int Agility { get; set; }

    public void UpdateAttributes(ActionType action)
    {
        switch (action)
        {
            case ActionType.HealthIncrease:
                Health += 20;
                break;
            case ActionType.StrengthIncrease:
                Strength += 5;
                break;
            case ActionType.AgilityIncrease:
                Agility += 3;
                break;
        }
    }
}
```
