#include <iostream>
using namespace std;

int main() {
    int n, k, count = 0;
    cin >> n >> k;

    // Use vector to store prime numbers
    vector<int> primes;

    // Loop from 2 to n and check if it is a prime number
    for (int i = 2; i <= n; i++) {
        bool isPrime = true;

        // Loop from 2 to sqrt(i) and check if i is divisible by any prime number in the vector
        for (int j = 0; j < primes.size(); j++) {
            if (i % primes[j] == 0) {
                isPrime = false;
                break;
            }
        }

        // If i is a prime number, add it to the vector
        if (isPrime) {
            primes.push_back(i);
        }
    }

    // Find kth prime number
    int kthPrime = 0;
    for (int i = 0; i < primes.size(); i++) {
        if (k == count) {
            kthPrime = primes[i];
            break;
        }
        count++;
    }

    // Print the kth prime number
    cout << kthPrime << endl;

    return 0;
}
```
This version of the code uses a `vector` to store the prime numbers, which makes it easier to check if a given number is a prime number and reduces the time complexity of the loop from O(n^2) to O(n). It also uses a `break` statement in the inner loop to stop searching for prime numbers as soon as the kth prime number is found.

