```
class EventManager:
    def __init__(self) -> None:
        self._callbacks = {}  # type: Dict[str, List[Callable]]

    def add_callback(self, event: str, callback: Callable[[Any], Any]) -> None:
        if not isinstance(event, str):
            raise TypeError("Event must be a string")
        if not callable(callback):
            raise TypeError("Callback must be a callable object")
        self._callbacks.setdefault(event, []).append(callback)

    def remove_callback(self, event: str, callback: Callable[[Any], Any]) -> None:
        if not isinstance(event, str):
            raise TypeError("Event must be a string")
        if not callable(callback):
            raise TypeError("Callback must be a callable object")
        self._callbacks[event].remove(callback)

    def trigger_event(self, event: str, *args: Any) -> None:
        if not isinstance(event, str):
            raise TypeError("Event must be a string")
        for callback in self._callbacks.get(event, []):
            callback(*args)
```
