def fibonacci_prime_product(m, p):
    if not m.isdigit() or not p.isdigit():
        raise ValueError("M and P must be integers")
    if int(m) < int(p):
        raise ValueError("M must be greater than or equal to P")

    fibonacci_sequence = [0, 1]
    prime_numbers = []

    for i in range(2, int(m) + 1):
        fibonacci_sequence.append((fibonacci_sequence[i - 1] + fibonacci_sequence[i - 2]) % 60)

    for i in range(2, int(m) + 1):
        if fibonacci_sequence[i] > int(p):
            prime_numbers.append(fibonacci_sequence[i])

    product = 1
    for prime in prime_numbers:
        product *= prime

    return product
