function logUserActivity($username, $action) {
    // Get the current timestamp and duration
    $timestamp = microtime(true);
    $duration = 0;

    // Check if a previous action exists for this user
    $previous_action = getPreviousAction($username);
    if ($previous_action !== false) {
        // Calculate the duration since the last action
        $duration = $timestamp - $previous_action['timestamp'];
    }

    // Insert the new action into the database
    $mysqli->query("INSERT INTO $table_name (username, action, timestamp, duration) VALUES ('$username', '$action', '$timestamp', '$duration')");
}

// Function to get the previous action for a user
function getPreviousAction($username) {
    // Query the database for the previous action
    $query = "SELECT * FROM $table_name WHERE username = '$username' ORDER BY timestamp DESC LIMIT 1";
    $result = $mysqli->query($query);

    // Check if a result was returned
    if ($result === false) {
        return false;
    } else {
        // Return the previous action
        return $result->fetch_assoc();
    }
}

// Function to limit the storage space used by the logs
function limitStorageSpace($limit) {
    // Query the database for the total size of the logs
    $query = "SELECT SUM(LENGTH(action)) AS total_size FROM $table_name";
    $result = $mysqli->query($query);

    // Check if a result was returned
    if ($result === false) {
        return;
    } else {
        // Calculate the current size of the logs
        $current_size = $result->fetch_assoc()['total_size'];

        // If the current size exceeds the limit, delete oldest logs
        if ($current_size > $limit) {
            $mysqli->query("DELETE FROM $table_name ORDER BY timestamp ASC LIMIT (SELECT CEILING(($current_size - $limit)/LENGTH(action)))");
        }
    }
}

// Function to retrieve logs for a category
function getLogsForCategory($category) {
    // Query the database for the logs for this category
    $query = "SELECT * FROM $table_name WHERE action LIKE '$category%'";
    $result = $mysqli->query($query);

    // Return the logs as an array
    return $result->fetch_all(MYSQLI_ASSOC);
}

// Function to retry failed database connections or queries with an exponential backoff strategy
function retryFailedConnection() {
    // Check if a previous connection attempt was successful
    if ($mysqli->connect_error) {
        // Sleep for a random amount of time before retrying
        sleep(mt_rand(1, 5));

        // Retry the failed connection or query
        $mysqli = new mysqli($host, $username, $password, $database);
    }
}

// Main function to log user activity and handle errors
