// Include necessary libraries
#include <iostream>
#include <cmath>

// Define a struct to represent a point in 2D space
struct Point {
    int x, y;
};

// Define a function to generate the Fibonacci sequence up to a given number
int fib(int n) {
    if (n <= 1) return n;
    else return fib(n-1) + fib(n-2);
}

// Define a function to calculate the distance between two points
float dist(Point p1, Point p2) {
    return sqrt((p2.x - p1.x)*(p2.x - p1.x) + (p2.y - p1.y)*(p2.y - p1.y));
}

// Define a function to generate the fractal pattern for a given point and scale factor
void generateFractal(Point p, int scale) {
    // Calculate the distance from the center of the fractal
    float distFromCenter = sqrt((p.x - 0.5)*(p.x - 0.5) + (p.y - 0.5)*(p.y - 0.5));

    // Calculate the Fibonacci number corresponding to the distance from the center
    int fibNumber = fib(floor(distFromCenter*scale));

    // Use the Fibonacci number to determine the color of the pixel
    if (fibNumber % 2 == 0) {
        std::cout << "Black";
    } else {
        std::cout << "White";
    }
}

// Define a function to generate the fractal pattern for a given point and scale factor, with multiple steps
void generateFractalMultiStep(Point p, int scale) {
    // Calculate the distance from the center of the fractal
    float distFromCenter = sqrt((p.x - 0.5)*(p.x - 0.5) + (p.y - 0.5)*(p.y - 0.5));

    // Calculate the Fibonacci number corresponding to the distance from the center, with multiple steps
    int fibNumber = 1;
    for (int i=0; i<scale-1; i++) {
        if (fibNumber % 2 == 0) {
            fibNumber += 1;
        } else {
            fibNumber -= 1;
        }
    }

    // Use the Fibonacci number to determine the color of the pixel
    if (fibNumber % 2 == 0) {
        std::cout << "Black";
    } else {
        std::cout << "White";
    }
}

int main() {
    // Define a point for the center of the fractal
    Point p(0.5, 0.5);

    // Define the scale factor for the fractal (in this case, we are using a scale factor of 3)
    int scale = 3;

    // Generate the fractal pattern for the given point and scale factor
    generateFractal(p, scale);

    return 0;
}

