[PYTHON]
public class BracketValidator {
    public boolean isValid(String input) {
        int balance = 0;
        for (char c : input.toCharArray()) {
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
                if (balance < 0) return false;
            } else if (c == '[') {
                balance++;
            } else if (c == ']') {
                balance--;
                if (balance < 0) return false;
            } else if (c == '{') {
                balance++;
            } else if (c == '}') {
                balance--;
                if (balance < 0) return false;
            }
        }
        return balance == 0;
    }
}
[/PYTHON]
