      </li>
    </ul>
  </nav>
  <div class="content">
    <ng-container *ngFor="let section of content | keyvalue; index as i;">
      <h2 [innerHTML]="getContent(i)"></h2>
      <p [innerHTML]="getContent(i+1)"></p>
