    if (!user) {
      throw new Error(`Invalid user ID ${userId}`);
    }
    const exchange = this.exchanges[exchangeId];
    if (!exchange) {
      throw new Error(`Invalid exchange ID ${exchangeId}`);
    }
    if (amount <= 0) {
      throw new Error('Invalid amount');
    }
    user.exchanges.push(exchangeId);
    exchange.deposits[userId] = amount;
  }

  user_deposit(userId, accountId, amount) {
    const user = this.users[userId];
    if (!user) {
      throw new Error(`Invalid user ID ${userId}`);
    }
    const account = this.accounts[accountId];
    if (!account) {
      throw new Error(`Invalid account ID ${accountId}`);
    }
    if (amount <= 0) {
      throw new Error('Invalid amount');
    }
    user.deposits[accountId] = amount;
  }

  transfer_to_session(userId, sessionId, amount) {
    const user = this.users[userId];
    if (!user) {
      throw new Error(`Invalid user ID ${userId}`);
    }
    const session = this.sessions[sessionId];
    if (!session) {
      throw new Error(`Invalid session ID ${sessionId}`);
    }
    if (amount <= 0) {
      throw new Error('Invalid amount');
    }
    user.transfers[sessionId] = amount;
  }
}
