def calculate_fibonacci(n):
    """
    Calculates the Fibonacci sequence up to the given number.

    Args:
        n (int): The maximum number in the Fibonacci sequence.

    Returns:
        list: A list of the first n numbers in the Fibonacci sequence.
    """

    if n <= 0:
        raise ValueError("n must be a positive integer.")

    memo = {0: 0, 1: 1}

    def recurse(i):
        if i in memo:
            return memo[i]
        else:
            result = recurse(i - 1) + recurse(i - 2)
            memo[i] = result
            return result

    fibonacci_seq = [recurse(i) for i in range(n)]
    even_sum = sum([i for i in fibonacci_seq if i % 2 == 0])
    return fibonacci_seq, even_sum

if __name__ == "__main__":
    n = int(input("Enter the maximum number in the Fibonacci sequence: "))
    try:
        fibonacci_seq, even_sum = calculate_fibonacci(n)
        print("Fibonacci sequence up to", n, ":", fibonacci_seq)
        print("Sum of all even numbers in the Fibonacci sequence up to", n, ":", even_sum)
    except ValueError:
        print("Invalid input. Please enter a positive integer.")

