Here is a revised version of the code with added comments and optimized request handling to manage rate limits:
```
const axios = require('axios');

// Define the API endpoint and headers for making requests
const apiEndpoint = 'https://api.example.com';
const headers = {
  'Content-Type': 'application/json',
  'Authorization': `Bearer ${process.env.API_TOKEN}`,
};

// Define the function to make a GET request to the API
async function getData(url) {
  const response = await axios.get(apiEndpoint + url, { headers });
  return response.data;
}

// Define the function to handle rate limits
const rateLimitHandler = async () => {
  if (Math.random() < 0.25) {
    // Randomly pause for a short period of time to avoid flooding the API
    await new Promise(resolve => setTimeout(resolve, Math.floor(Math.random() * 1000)));
  } else {
    // Otherwise, check if the rate limit has been exceeded and wait until it's reset
    const response = await axios.get(`${apiEndpoint}/rate_limit`);
    if (response.data.remaining < 1) {
      const delay = response.data.reset - Date.now() + 500; // Add a 500ms buffer to account for network latency
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
}

// Define the function to make multiple GET requests in parallel and handle rate limits
async function getMultipleData(urls) {
  // Split the URLs into chunks of 10 to avoid exceeding the maximum number of requests per minute
  const urlChunks = urls.chunk(10);
  const data = [];

  for (const chunk of urlChunks) {
    await rateLimitHandler();
    const responses = await Promise.all(chunk.map(url => getData(url)));
    data.push(...responses.flat());
  }

  return data;
}

// Use the functions to make GET requests and handle rate limits
const urls = ['/endpoint1', '/endpoint2'];
const data = await getMultipleData(urls);
console.log(data);
```
In this revised version of the code, we have added comments to explain the main blocks of the code for better understandability. We have also optimized the request handling to manage rate limits by randomly pausing for a short period of time or checking if the rate limit has been exceeded and waiting until it's reset. Additionally, we have split the URLs into chunks of 10 to avoid exceeding the maximum number of requests per minute.

