// This function takes in a string as input and returns its reverse
function reverseString(str) {
  // Create an empty array to store the reversed string
  let reversed = [];

  // Loop through each character of the input string
  for (let i = str.length - 1; i >= 0; i--) {
    // Add the current character to the end of the reversed array
    reversed.push(str[i]);
  }

  // Join the characters in the reversed array into a string and return it
  return reversed.join('');
}
```
