```
// Create an array to store the word to guess
var word = ['_', '_', '_'];

// Set up the HTML elements for the game board
var gameBoard = document.getElementById('game-board');
var hangmanWord = document.createElement('div');
hangmanWord.className = 'hangman-word';
gameBoard.appendChild(hangmanWord);

// Create an array to store the guessed letters
var guessedLetters = [];

// Set up the game over variables
var gameOver = false;
var numberOfGuessesRemaining = 8;

// Add event listeners to the buttons on the game board
for (var i = 0; i < 12; i++) {
  var button = document.createElement('button');
  button.className = 'hangman-button';
  hangmanWord.appendChild(button);
}

// Add event listeners to the buttons on the game board
for (var i = 0; i < 12; i++) {
  var button = document.getElementById('hangman-button' + i);
  button.addEventListener('click', function() {
    guessLetter(this.textContent);
  });
}

// Function to guess a letter
function guessLetter(letter) {
  // Check if the letter has already been guessed
  if (guessedLetters.includes(letter)) {
    alert('You have already guessed that letter!');
    return;
  }

  // Add the letter to the list of guessed letters
  guessedLetters.push(letter);

  // Check if the letter is in the word to guess
  if (word.includes(letter)) {
    // Replace the underscores with the guessed letter
    var index = word.indexOf(letter);
    while (index !== -1) {
      word[index] = letter;
      index = word.indexOf(letter, index + 1);
    }
    // Update the game board
    updateGameBoard();
  } else {
    numberOfGuessesRemaining--;
    if (numberOfGuessesRemaining === 0) {
      gameOver = true;
    }
    // Update the game board
    updateGameBoard();
  }
}

// Function to update the game board
function updateGameBoard() {
  for (var i = 0; i < word.length; i++) {
    var letter = word[i];
    if (letter === '_') {
      document.getElementById('hangman-button' + i).textContent = '__';
    } else {
      document.getElementById('hangman-button' + i).textContent = letter;
    }
  }
}

// Function to start a new game
function startNewGame() {
  // Reset the word and guessed letters arrays
  word = ['_', '_', '_'];
  guessedLetters = [];

  // Reset the number of guesses remaining
  numberOfGuessesRemaining = 8;

  // Reset the game over variable
  gameOver = false;

  // Update the game board
  updateGameBoard();
}
```
This code creates an array to store the word to guess and another array to store the guessed letters. It also sets up the HTML elements for the game board and adds event listeners to the buttons on the board. The `guessLetter` function is called when a button is clicked, and it checks if the letter has already been guessed, replaces the underscores with the guessed letter in the word array, updates the game board, and checks if the letter is in the word to guess. If it is not, it decrements the number of guesses remaining and checks if the game is over. The `updateGameBoard` function updates the game board by replacing underscores with guessed letters and hiding buttons that have already been guessed. The `startNewGame` function resets the arrays and variables for a new game.

