class AdvancedDroneControlSystem:
    def __init__(self, drone):
        self.drone = drone
        self.current_state = "idle"
        self.mission_queue = []

    def takeoff(self):
        self.drone.takeoff()
        self.current_state = "taking off"

    def land(self):
        self.drone.land()
        self.current_state = "landing"

    def go_to_location(self, x, y, z):
        self.drone.go_to_location(x, y, z)
        self.current_state = "flying to location"

    def start_mission(self):
        self.current_state = "starting mission"
        if len(self.mission_queue) > 0:
            next_waypoint = self.mission_queue[0]
            self.go_to_location(next_waypoint[0], next_waypoint[1], next_waypoint[2])

    def add_to_mission_queue(self, waypoints):
        for waypoint in waypoints:
