            next_waypoint = self.mission_queue[0]
            self.go_to_location(next_waypoint[0], next_waypoint[1], next_waypoint[2])
            self.mission_queue.pop(0)

    def abort_current_mission(self):
        self.drone.land()
        self.current_state = "idle"
        self.mission_queue = []

