You can use a combination of regular expressions and the `ts.SyntaxKind` constants from the TypeScript library to extract the information you need. Here's an example function that should do what you described:
```typescript
import { ts } from 'typescript';

function extractAngularComponents(input: string): string[] {
  const sourceFile = ts.createSourceFile('test.ts', input, ts.ScriptTarget.Latest, true);
  const components = [];

  // Iterate over all the nodes in the source file and look for component definitions
  sourceFile.statements.forEach(statement => {
    if (statement.kind === ts.SyntaxKind.ClassDeclaration) {
      const classDeclaration = statement as ts.ClassDeclaration;
      // Check if the class is an Angular component by looking for the `@Component` decorator
      if (classDeclaration.decorators && classDeclaration.decorators[0].expression.getText() === '@Component') {
        components.push(classDeclaration.name);
      }
    } else if (statement.kind === ts.SyntaxKind.ImportEqualsDeclaration) {
      const importEqualsDeclaration = statement as ts.ImportEqualsDeclaration;
      // Check if the import is an Angular component by looking for the `AngularComponent` interface
      if (importEqualsDeclaration.expression.getText().indexOf('AngularComponent') !== -1) {
        components.push(importEqualsDeclaration.name);
      }
    }
  });

  return components;
}
```
This function takes an input string as a parameter and creates a TypeScript `SourceFile` object from it using the `ts.createSourceFile()` method. It then iterates over all the nodes in the source file and looks for component definitions by checking if they are class declarations with the `@Component` decorator, or import declarations that import Angular components. If a component is found, its name is added to the list of components.

