def count_strings(string_list):
    vowel_e_count = 0
    consonant_count = 0
    third_char_a_count = 0
    for string in string_list:
        if string == "":
            continue # skip empty strings
        elif string.isdigit():
            continue # skip strings that are only digits
        elif string[0].isalpha() and string[-1] == "e":
            vowel_e_count += 1
        elif string[0].isalpha() and string[2] == "a":
            third_char_a_count += 1
        else:
            consonant_count += 1
    return (vowel_e_count, consonant_count, third_char_a_count)

