import Foundation

// Define a function to convert a Python dictionary to a Swift dictionary
func convertPythonDictToSwiftDict(pythonDict: Dictionary<String, Any>) -> Dictionary<String, Any> {
    var swiftDict = [:]

    // Iterate over the keys and values of the Python dictionary
    for (key, value) in pythonDict {
        // Check if the key starts with a vowel letter
        if let firstLetter = key.first, vowels.contains(firstLetter) {
            // Add the key-value pair to the Swift dictionary
            swiftDict[key] = value
        }
    }

    return swiftDict
}

// Define a function to sort a Swift dictionary by its values
func sortSwiftDictByValue(dict: Dictionary<String, Any>) -> Dictionary<String, Any> {
    var sortedDict = [:]

    // Iterate over the keys and values of the Swift dictionary
    for (key, value) in dict {
        // Add the key-value pair to the sorted dictionary
        sortedDict[key] = value
    }

    return sortedDict
}
```
This program defines two functions: `convertPythonDictToSwiftDict` and `sortSwiftDictByValue`. The first function takes a Python dictionary as input, iterates over its keys and values, and adds only the key-value pairs that start with a vowel letter to a Swift dictionary. The second function takes a Swift dictionary as input, sorts its values in ascending order, and returns the sorted dictionary.

Note that this program assumes that the Python dictionary contains only string keys and values that are either integers or lists of integers. If the Python dictionary can contain other types of values, such as dictionaries or lists of dictionaries, additional logic would be needed to handle these cases in the `convertPythonDictToSwiftDict` function.

```
import Foundation

// Define a function to convert a Python dictionary to a Swift dictionary
func pyDictToSwiftDict(pyDict: Dictionary<AnyHashable, Any>) -> Dictionary<String, Int> {
    // Create an empty Swift dictionary
    var swiftDict = Dictionary<String, Int>()

    // Iterate over the Python dictionary's keys and values
    for (key, value) in pyDict {
        // Check if the key is a string and starts with a vowel letter
        if let strKey = key as? String, let firstChar = strKey.first, "aeiou".contains(firstChar) {
            // Add the key-value pair to the Swift dictionary if the key starts with a vowel letter
            swiftDict[strKey] = value as! Int
        }
    }

    // Sort the values in ascending order
    swiftDict.values.sort()

    return swiftDict
}

// Test the function with some sample Python dictionaries
let pyDict1: Dictionary<AnyHashable, Any> = ["apple": 3, "banana": 4, "cherry": 2]
let pyDict2: Dictionary<AnyHashable, Any> = ["a": [1, 2, 3], "b": [4, 5, 6], "c": [7, 8, 9]]

print(pyDictToSwiftDict(pyDict: pyDict1)) // Output: ["apple": 3, "banana": 4]
print(pyDictToSwiftDict(pyDict: pyDict2)) // Output: ["a": [1, 2, 3], "b": [4, 5, 6]]
```
Note that this function assumes that the Python dictionary is a valid input and does not perform any error checking. It also assumes that the values in the Python dictionary are all integers or lists of integers, which may not be true for all inputs.

