[javascript]
const http = require('http');

function processForm(formData) {
    // Get the part ID and name from the form data
    const partId = formData.partID[0];
    const partName = formData.partname[0];

    // Check if there are any other packages to add
    if (Object.keys(formData).length === 2) {
        // There are no other packages to add, display a message to the user
        return { message: 'No other packages to add.' };
    } else {
        // Add the selected part to the shopping cart
        const shoppingCart = {};
        shoppingCart[partId] = partName;

        return { message: `Part ${partName} added to shopping cart.` };
    }
}

const options = {
    method: 'POST',
    headers: {
        'Content-Type': 'application/json'
    },
    body: JSON.stringify(processForm(formData))
};

http.request(options, (response) => {
    const statusCode = response.statusCode;
    const contentType = response.headers['content-type'];

    let error;
    if (statusCode !== 200) {
        error = new Error('Request Failed.\n' + `Status Code: ${statusCode}`);
    } else if (!/^application\/json/.test(contentType)) {
        error = new Error(`Invalid content-type.\nExpected application/json but received ${contentType}`);
    }
    if (error) {
        console.log(error.message);
        // consume response data to free up memory
        response.resume();
        return;
    }

    response.setEncoding('utf8');
    let rawData = '';
    response.on('data', (chunk) => { rawData += chunk; });
    response.on('end', () => {
        try {
            const parsedData = JSON.parse(rawData);
            console.log(parsedData);
        } catch (e) {
            console.error(e.message);
        }
    });
}).end();
