main :: IO ()
main = do
  -- Get the part ID and name from the form data
  let partId = head $_POST["partID"]
      partName = head $_POST["partname"]

  -- Check if there are any other packages to add
  if length $_POST == 2 then
    -- There are no other packages to add, display a message to the user
    let response = object [ "message" .= String "No other packages to add." ]
  else
    -- Add the selected part to the shopping cart
    let shoppingCart = object [partId .= partName]
        response = object [ "message" .= String (show (partName ++ " added to shopping cart.")) ]

  -- Output the response
  sendResponse $ response

sendResponse :: Object -> IO ()
sendResponse response = do
  let body = encode response
      request = parseUrl "http://example.com"

  response <- httpLbs (setRequestBodyLBS body request) httpManager
  print $ getResponseStatusCode response
