```java
public class Student {
    private int id;
    private String name;
    private int grade;

    // Constructor
    public Student(int id, String name, int grade) {
        this.id = id;
        this.name = name;
        this.grade = grade;
    }

    // Getter methods
    public int getId() {
        return id;
    }
    public String getName() {
        return name;
    }
    public int getGrade() {
        return grade;
    }

    // Setter methods
    public void setId(int id) {
        this.id = id;
    }
    public void setName(String name) {
        this.name = name;
    }
    public void setGrade(int grade) {
        this.grade = grade;
    }

    // Method to calculate the average grade of all students in the class
    public static int getAverageGrade(List<Student> students) {
        if (students == null || students.size() == 0) {
            return -1;
        }

        int sum = 0;
        for (Student student : students) {
            sum += student.getGrade();
        }

        return sum / students.size();
    }

    // Method to get the top performing student in the class
    public static Student getTopPerformingStudent(List<Student> students) {
        if (students == null || students.size() == 0) {
            return null;
        }

        Student topStudent = null;
        for (Student student : students) {
            if (topStudent == null || topStudent.getGrade() < student.getGrade()) {
                topStudent = student;
            }
        }

        return topStudent;
    }

    // Method to get a list of students with grades above the specified grade
    public static List<Student> getStudentsWithGradeAbove(List<Student> students, int grade) {
        if (students == null || students.size() == 0) {
            return Collections.emptyList();
        }

        List<Student> studentsWithGradeAbove = new ArrayList<>();
        for (Student student : students) {
            if (student.getGrade() > grade) {
                studentsWithGradeAbove.add(student);
            }
        }

        return studentsWithGradeAbove;
    }

    // Method to remove a student with the given id from the class
    public static void removeStudent(List<Student> students, int id) {
        if (students == null || students.size() == 0) {
            return;
        }

        for (int i = 0; i < students.size(); i++) {
            Student student = students.get(i);
            if (student.getId() == id) {
                students.remove(i);
                break;
            }
        }
    }

    // Method to update the grade of a student with the given id to the new grade
    public static void updateGrade(List<Student> students, int id, int newGrade) {
        if (students == null || students.size() == 0) {
            return;
        }

        for (int i = 0; i < students.size(); i++) {
            Student student = students.get(i);
            if (student.getId() == id) {
                student.setGrade(newGrade);
                break;
            }
        }
    }
}
```
This class has the following methods:

