And here is the JavaScript code that implements client-side validation and email address validation:
```
// Get all form elements
var form = document.getElementById("contactForm");
var nameInput = document.getElementById("name");
var emailInput = document.getElementById("email");
var messageInput = document.getElementById("message");
var subjectInput = document.getElementById("subject");

// Validate name and email address on blur event
nameInput.addEventListener("blur", function() {
  if (this.value == "") {
    alert("Name cannot be empty.");
  }
});

emailInput.addEventListener("blur", function() {
  if (!validateEmail(this.value)) {
    alert("Invalid email address.");
  }
});

// Validate message and subject line on submit event
form.addEventListener("submit", function(event) {
  var isValid = true;

  // Check name field
  if (nameInput.value == "") {
    isValid = false;
    alert("Name cannot be empty.");
  }

  // Check email address field
  if (!validateEmail(emailInput.value)) {
    isValid = false;
    alert("Invalid email address.");
  }

  // Check message field
  if (messageInput.value == "") {
    isValid = false;
    alert("Message cannot be empty.");
  }

  // Check subject line field
  if (subjectInput.value == "") {
    isValid = false;
    alert("Subject line cannot be empty.");
  }

  if (!isValid) {
    event.preventDefault();
  }
});

// Validate email address using a regular expression
function validateEmail(email) {
  var re = /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
  return re.test(email);
}
```
Note that this is just an example and you should adjust the validation rules to suit your specific needs.

