import bz2

def compress_decompress_file(compression, filepath_or_buffer, mode):
    if compression == "gzip":
        import gzip
        if mode.startswith("r"):
            return gzip.open(filepath_or_buffer, mode)
        else:
            with open(filepath_or_buffer, mode) as f_in:
                with gzip.open(f_in, "rb") as f_out:
                    return f_out.read()
    elif compression == "bz2":
        if mode.startswith("r"):
            return bz2.open(filepath_or_buffer, mode)
        else:
            with open(filepath_or_buffer, mode) as f_in:
                with bz2.open(f_in, "rb") as f_out:
                    return f_out.read()
    else:
        raise ValueError("Invalid compression algorithm")
[/PYTHON]
[TESTS]
