import React, { useState } from 'react';

const BlogPost = () => {
  const [likes, setLikes] = useState(0);
  const [comments, setComments] = useState([]);
  const [editingComment, setEditingComment] = useState(null); // Add a state variable to keep track of the comment being edited
  const [deletingComment, setDeletingComment] = useState(null); // Add a state variable to keep track of the comment being deleted
  const [replyingToComment, setReplyingToComment] = useState(null); // Add a state variable to keep track of the comment being replied to

  const handleLike = () => {
    setLikes(likes + 1); // Increases the number of likes instead of decreasing it
  };

  const handleCommentSubmit = (comment) => {
    setComments([...comments, comment]);
  };

  const handleEditComment = (comment) => {
    setEditingComment(comment); // Set the comment being edited to the one being clicked on
  };

  const handleDeleteComment = (comment) => {
    setDeletingComment(comment); // Set the comment being deleted to the one being clicked on
  };

  const handleReplyToComment = (comment) => {
    setReplyingToComment(comment); // Set the comment being replied to to the one being clicked on
  };

  const handleEditSubmit = (editedComment) => {
    const updatedComments = comments.map((c) => c === editingComment ? editedComment : c);
    setComments(updatedComments);
    setEditingComment(null); // Clear the state variable keeping track of the comment being edited
  };

  const handleDeleteSubmit = (deletedComment) => {
    const updatedComments = comments.filter((c) => c !== deletingComment);
    setComments(updatedComments);
    setDeletingComment(null); // Clear the state variable keeping track of the comment being deleted
  };

  const handleReplySubmit = (repliedComment) => {
    const updatedComments = comments.map((c) => c === replyingToComment ? [...c, repliedComment] : c);
    setComments(updatedComments);
    setReplyingToComment(null); // Clear the state variable keeping track of the comment being replied to
  };

  return (
    <div>
      <h1>Blog Post Title</h1>
      <p>Author: John Doe</p>
      <p>Date: September 1, 2022</p>
      <p>Likes: {likes}</p>
      <button onClick={handleLike}>Like</button>
      <hr />
      <h2>Comments</h2>
      {comments.map((comment) => (
        <div key={comment.id}>
          <p>{comment.text}</p>
          <p>Author: {comment.author}</p>
          <p>Date: {new Date(comment.date).toLocaleString()}</p>
          <button onClick={() => handleEditComment(comment)}>Edit</button>
          <button onClick={() => handleDeleteComment(comment)}>Delete</button>
          <hr />
        </div>
      ))}
      {editingComment && (
        <EditCommentForm comment={editingComment} onSubmit={handleEditSubmit} />
      )}
      {deletingComment && (
        <ConfirmationPrompt
          prompt="Are you sure you want to delete this comment?"
          onCancel={() => setDeletingComment(null)}
          onConfirm={() => handleDeleteSubmit(deletingComment)}
        />
      )}
      {replyingToComment && (
        <ReplyForm comment={replyingToComment} onSubmit={handleReplySubmit} />
      )}
    </div>
  );
};
```
