def monotonic(l: list, strict: bool = False):
    """
    Return True if list elements are monotonically increasing or decreasing, factoring in the strictness requirement.
    If strict is set to True, adjacent elements must not be identical; otherwise, they may be the same.

    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 1, 0, -10], strict=True)
    False
    >>> monotonic([1, 1, 1, 1], strict=False)
    True

    """
    if len(l) < 2:
        return True

    if l[0] > l[-1]:
        return all(x >= y for x, y in zip(l, l[1:]))
    elif l[0] < l[-1]:
        return all(x <= y for x, y in zip(l, l[1:]))
    else:
        if strict:
            return all(x != y for x, y in zip(l, l[1:]))
        else:
            return True

