[PYTHON]
function bubbleSort(str) {
  var sorted = false;
  while (!sorted) {
    sorted = true;
    for (var i = 0; i < str.length - 1; i++) {
      if (str[i] > str[i + 1]) {
        var temp = str[i];
        str[i] = str[i + 1];
        str[i + 1] = temp;
        sorted = false;
      }
    }
  }
  return str;
}
[/PYTHON]
