def is_happy(s):
    """You are given a string s.
    Determine whether the string is happy or not.
    A string is regarded as happy if it is at least 3 characters long, each consecutive set of 3 characters are distinct, every unique character appears at least twice, but not more than four times, and no character appears thrice in a consecutive sequence.

    For instance:
    is_happy(a) => False
    is_happy(aa) => False
    is_happy(abcd) => False
    is_happy(aabb) => False
    is_happy(adbbd) => True
    is_happy(xyzz) => False
    """
    if len(s) < 3:
        return False

    # check for distinct consecutive sets of 3 characters
    for i in range(len(s) - 2):
        if s[i] == s[i+1] == s[i+2]:
            return False

    # check for unique characters and their frequency
    char_freq = {}
    for c in s:
        if c not in char_freq:
            char_freq[c] = 1
        else:
            char_freq[c] += 1

    # check for maximum frequency of each character
    for c, freq in char_freq.items():
        if freq > 4:
            return False

    # check for thrice consecutive sequence
    for i in range(len(s) - 2):
        if s[i] == s[i+1] and s[i+1] == s[i+2]:
            return False

    return True

