    Ascertain whether the string is happy or not.
    A string is described as happy if it is at least 3 characters long, each consolidative set of 3 characters are individual, every unique character appears no less than twice, and no character appears thrice in a direct sequence.

    For instance:
    is_happy(a) => False
    is_happy(aa) => False
    is_happy(abcd) => False
    is_happy(aabb) => False
    is_happy(adbbd) => True
    is_happy(xyzz) => False
    """
    # Check if the string is at least 3 characters long
    if len(s) < 3:
        return False

    # Create a dictionary to store the frequency of each character in the string
    char_freq = {}
    for char in s:
        if char not in char_freq:
            char_freq[char] = 1
        else:
            char_freq[char] += 1

    # Check if every unique character appears no less than twice
    for char, freq in char_freq.items():
        if freq == 1:
            return False

    # Check if no character appears thrice in a direct sequence
    for i in range(len(s) - 2):
        if s[i] == s[i+1] and s[i+1] == s[i+2]:
            return False

    return True

