        socket.on('newMessage', function(message) {
            var msg = document.createElement("li");
            msg.innerHTML = message;
            document.getElementById("messages").appendChild(msg);
        });

        // Listen for a new user event and update the messages list
        socket.on('newUser', function(message) {
            var msg = document.createElement("li");
            msg.innerHTML = message;
            document.getElementById("messages").appendChild(msg);
        });

        // Listen for a disconnect event and update the messages list
        socket.on('disconnect', function() {
            var msg = document.createElement("li");
            msg.innerHTML = "User disconnected";
            document.getElementById("messages").appendChild(msg);
        });

        // Listen for a connect event and update the messages list
        socket.on('connect', function() {
            var msg = document.createElement("li");
            msg.innerHTML = "User connected";
            document.getElementById("messages").appendChild(msg);
        });

        // Send a message to the server when the form is submitted
        document.querySelector("form").addEventListener("submit", function(e) {
            e.preventDefault();
            var msg = document.querySelector("#message");
            socket.emit("sendMessage", msg.value);
            msg.value = "";
        });
    </script>
</body>
</html>
