  snowflakeGroup.children.forEach(function(snowflake) {
    var velocity = new THREE.Vector3(0, -1, 0);
    var acceleration = new THREE.Vector3(0, -0.05, 0);
    snowflake.position.add(velocity);
    snowflake.position.add(acceleration);
    if (snowflake.position.y < -1) {
      snowflake.position.y = 1;
    }
    snowflake.scale.x = Math.abs(snowflake.position.y * 0.2);
    snowflake.scale.y = snowflake.scale.x;
    snowflake.scale.z = snowflake.scale.x;
  });
}

// Animate the scene and update the snowflakes
