```
// Initialize the GL context
var gl = canvas.getContext("webgl");

// Set up the vertex buffer object (VBO) for the snowflakes
var vbo = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([
  // x, y, size, angle, speed, color
  0, 0, 10, 0, 5, [1, 1, 1],
  10, 10, 20, 45, 7, [1, 1, 1],
  20, 20, 30, 90, 10, [1, 1, 1]
]), gl.STATIC_DRAW);

// Set up the vertex shader
var vertShader = gl.createShader(gl.VERTEX_SHADER);
gl.shaderSource(vertShader, `
  attribute vec2 position;
  attribute float size;
  attribute float angle;
  attribute float speed;
  attribute vec3 color;

  void main() {
    gl_Position = vec4(position * size, 0, 1);
    gl_PointSize = speed;
  }
`);
gl.compileShader(vertShader);

// Set up the fragment shader
var fragShader = gl.createShader(gl.FRAGMENT_SHADER);
gl.shaderSource(fragShader, `
  precision mediump float;
  varying vec3 vColor;

  void main() {
    gl_FragColor = vec4(vColor, 1);
  }
`);
gl.compileShader(fragShader);

// Create the program and link it with the shaders
var program = gl.createProgram();
gl.attachShader(program, vertShader);
gl.attachShader(program, fragShader);
gl.linkProgram(program);

// Set up the vertex attribute pointers
gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
var position = gl.getAttribLocation(program, "position");
var size = gl.getAttribLocation(program, "size");
var angle = gl.getAttribLocation(program, "angle");
var speed = gl.getAttribLocation(program, "speed");
var color = gl.getAttribLocation(program, "color");
gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 0, 0);
gl.vertexAttribPointer(size, 1, gl.FLOAT, false, 0, 8);
gl.vertexAttribPointer(angle, 1, gl.FLOAT, false, 0, 12);
gl.vertexAttribPointer(speed, 1, gl.FLOAT, false, 0, 16);
gl.vertexAttribPointer(color, 3, gl.FLOAT, false, 0, 20);

// Set up the uniforms
var projectionMatrix = mat4.create();
mat4.perspective(projectionMatrix, Math.PI / 2, canvas.width / canvas.height, 0.1, 1000);
var modelViewMatrix = mat4.create();
var viewMatrix = mat4.create();
var projectionViewModelMatrix = mat4.multiply(projectionMatrix, viewMatrix, modelViewMatrix);
gl.uniformMatrix4fv(program.uniforms["u_ProjectionViewModelMatrix"], false, projectionViewModelMatrix);

// Set up the framebuffer and render buffer for the snowfall effect
var fb = gl.createFramebuffer();
gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
var rb = gl.createRenderbuffer();
gl.bindRenderbuffer(gl.RENDERBUFFER, rb);
gl.renderbufferStorage(gl.RENDERBUFFER, gl.DEPTH_COMPONENT16, canvas.width, canvas.height);
gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, rb, 0);
var snowfallTexture = gl.createTexture();
gl.bindTexture(gl.TEXTURE_2D, snowfallTexture);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
gl.generateMipmap(snowfallTexture);
gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, snowfallTexture, 0);

// Set up the uniform for the snowfall texture
var snowfallTextureUniform = program.uniforms["u_SnowfallTexture"];
gl.uniform1i(snowfallTextureUniform, 0);

// Draw the snowflakes
var snowflakeCount = 50;
for (var i = 0; i < snowflakeCount; ++i) {
  gl.drawArrays(gl.POINTS, i * 3, 3);
}
