```
class Triangle:
    def __init__(self, side_a, side_b, side_c):
        self.side_a = side_a
        self.side_b = side_b
        self.side_c = side_c
        self.angles = [0, 0, 0]
        self.inradius = 0
        self.type = "Unknown"

    def set_sides(self, side_a, side_b, side_c):
        if not all([side_a > 0, side_b > 0, side_c > 0]):
            raise ValueError("All sides must be positive")
        self.side_a = side_a
        self.side_b = side_b
        self.side_c = side_c

    def set_angles(self, angle_a, angle_b, angle_c):
        if not all([angle_a >= 0, angle_b >= 0, angle_c >= 0]):
            raise ValueError("All angles must be non-negative")
        self.angle_a = angle_a
        self.angle_b = angle_b
        self.angle_c = angle_c

    def set_inradius(self, inradius):
        if not inradius > 0:
            raise ValueError("Inradius must be positive")
        self.inradius = inradius

    def get_area(self):
        return (self.side_a + self.side_b + self.side_c) * 2

    def get_perimeter(self):
        return self.side_a + self.side_b + self.side_c

    def is_equilateral(self):
        if self.side_a == self.side_b and self.side_b == self.side_c:
            return True
        else:
            return False

    def is_isosceles(self):
        if self.side_a == self.side_b or self.side_b == self.side_c:
            return True
        else:
            return False

    def is_scalene(self):
        if self.side_a != self.side_b and self.side_b != self.side_c:
            return True
        else:
            return False

    def is_acute(self):
        if all([angle_a < 90, angle_b < 90, angle_c < 90]):
            return True
        else:
            return False

    def is_right(self):
        if any([angle_a == 90, angle_b == 90, angle_c == 90]):
            return True
        else:
            return False

    def is_obtuse(self):
        if all([angle_a > 90, angle_b > 90, angle_c > 90]):
            return True
        else:
            return False
```
This class represents a triangle and has methods to calculate its properties, such as the area and perimeter. It also has methods to determine the type of triangle based on side lengths and angle sizes. The class also includes input validation to ensure that only valid triangles are created.

Here is an example usage:
```
triangle = Triangle(3, 4, 5)
print(triangle.get_area()) # prints 6
