[PYTHON]
from math import degrees, sqrt
from typing import Tuple

def get_angle(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> float:
    a = sqrt((q[0] - p[0]) ** 2 + (q[1] - p[1]) ** 2)
    b = sqrt((q[0] - r[0]) ** 2 + (q[1] - r[1]) ** 2)
    c = sqrt((p[0] - r[0]) ** 2 + (p[1] - r[1]) ** 2)
    return degrees(acos((a ** 2 + b ** 2 - c ** 2) / (2 * a * b)))

def triangle_type(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> str:
    angle_a = get_angle(p, q, r)
    angle_b = get_angle(q, r, p)
    angle_c = get_angle(r, p, q)
    if angle_a + angle_b + angle_c == 180:
        return 'Equilateral'
    elif angle_a == angle_b == angle_c:
        return 'Isosceles'
    else:
        return 'Scalene'
[/PYTHON]

