def determine_triangle_type(side1, side2, side3):
  if not (isinstance(side1, int) or isinstance(side1, float)): raise TypeError("Argument 'side1' must be a number.")
  if not (isinstance(side2, int) or isinstance(side2, float)): raise TypeError("Argument 'side2' must be a number.")
  if not (isinstance(side3, int) or isinstance(side3, float)): raise TypeError("Argument 'side3' must be a number.")

  side1 = float(side1)
  side2 = float(side2)
  side3 = float(side3)

  if (side1 + side2 > side3 and side2 + side3 > side1 and side1 + side3 > side2):
    return "scalene"
  elif (side1 == side2 == side3):
    return "equilateral"
  else:
    return "isosceles"

[PYTHON]
class Result:
    def __init__(self, value):
        self.value = value

    @staticmethod
    def ok(value):
        return Result(value)

    @staticmethod
    def err(error):
        return Result(None, error)

    def flatMap(self, func):
        if self.isErr():
            return Err(self.error)
        else:
            return func(self.value)

    def isErr(self):
        return self.value is None

    def expectErr(self, error):
        if self.isErr() and self.error == error:
            return
        raise ValueError("Unexpected result value")
[/PYTHON]
