[PYTHON]
def get_greatest_common_divisor(a, b):
    if a == 0 and b == 0:
        return 0
    if a < 0 or b < 0:
        print("Both numbers must be positive.")
        return -1
    if a == 0 or b == 0:
        print("Both numbers must be non-zero.")
        return -1
    divisor = 1
    for i in range(1, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            divisor = i
    return divisor
