const form = document.getElementById("color-mixer-form");
const primaryColorInput = document.getElementById("primary-color");
const secondaryColorInput = document.getElementById("secondary-color");
const mixedColorDisplay = document.getElementById("mixed-color");
let primaryColor;
let secondaryColor;
let mixedColor;

function getColors() {
  const validatedPrimaryColor = validateHexCode(primaryColorInput.value);
  if (!validatedPrimaryColor) {
    console.error(`Invalid Primary Color: ${primaryColorInput.value}`);
    return;
  }
  primaryColor = validatedPrimaryColor;

  const validatedSecondaryColor = validateHexCode(secondaryColorInput.value);
  if (!validatedSecondaryColor) {
    console.error(`Invalid Secondary Color: ${secondaryColorInput.value}`);
    return;
  }
  secondaryColor = validatedSecondaryColor;
}

function validateHexCode(hexCode) {
  const hexPattern = /^#[0-9A-F]{6}$/i;
  if (hexPattern.test(hexCode)) {
    return hexCode;
  } else {
    return null;
  }
}

function mixColors() {
  const red1 = parseInt(primaryColor.substring(1, 3), 16);
  const green1 = parseInt(primaryColor.substring(3, 5), 16);
  const blue1 = parseInt(primaryColor.substring(5), 16);
  const red2 = parseInt(secondaryColor.substring(1, 3), 16);
  const green2 = parseInt(secondaryColor.substring(3, 5), 16);
  const blue2 = parseInt(secondaryColor.substring(5), 16);
  mixedColor = `rgb(${Math.floor((red1 + red2) / 2)}, ${Math.floor((green1 + green2) / 2)}, ${Math.floor((blue1 + blue2) / 2)})`;
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  getColors();
  if (!primaryColor || !secondaryColor) return;
  mixColors();
  mixedColorDisplay.style.backgroundColor = mixedColor;
});
```
