import libcst as cst
from typing import Dict, Any

class StringCollector:
    def __init__(self):
        self.contexts = []

    def open_module(self, fullname: str):
        self.current_context = {"fullname": fullname}
        self.contexts.append(self.current_context)

    def visit(self, tree: cst.CSTNode):
        if isinstance(tree, cst.BaseCompoundStatement):
            for element in tree.elements:
                self.visit(element)
        elif isinstance(tree, cst.Assign):
            self.current_context["assign"] = str(tree)
        elif isinstance(tree, cst.AnnAssign):
            self.current_context["annassign"] = str(tree)

def walk_files(pattern: str):
    # Implementation not shown for brevity
    pass

def collect(pattern: str) -> Dict[str, Any]:
    contexts = []
    for root, name, fullname in walk_files(pattern):
        print(f"Parsing {fullname}")
        with open(fullname) as f:
            tree = cst.metadata.MetadataWrapper(cst.parse_module(f.read()))
            collector = StringCollector()
            collector.open_module(fullname)
            tree.visit(collector)
            contexts.append(collector.current_context)
    return {"files": contexts}
