// Set up interactive features such as hovering over a segment to display its value and clicking on a segment to highlight it
category.on('mouseover', function() {
  const category = d3.select(this).data().category;
  const value = d3.select(this).data().value;
  const subcategories = combinedData.filter(data => data.category === category);
