```
#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Function to generate a list of prime numbers up to a given number
void generate_prime_numbers(int n, int *primes) {
    // Initialize the first two primes (2 and 3)
    primes[0] = 2;
    primes[1] = 3;
    int i = 2, j = 0, count = 0;

    while (i <= n) {
        // Check if the number is divisible by any prime numbers less than itself
        for (j = 0; j < count; j++) {
            if (i % primes[j] == 0) {
                break;
            }
        }

        // If the number is not divisible by any prime numbers less than itself, then it is a prime number
        if (j == count) {
            primes[++count] = i++;
        } else {
            i++;
        }
    }
}

// Function to check if an input number is prime or not
int is_prime(int n, int *primes) {
    // Generate a list of prime numbers up to the input number
    generate_prime_numbers(n, primes);

    // Check if the input number is divisible by any prime numbers less than itself
    for (int i = 0; i < count; i++) {
        if (n % primes[i] == 0) {
            return 1;
        }
    }

    // Generate a list of prime numbers greater than the input number
    generate_prime_numbers(sqrt(n), primes);

    // Check if the input number is divisible by any prime numbers greater than itself
    for (int i = 0; i < count; i++) {
        if (n % primes[i] == 0) {
            return 1;
        }
    }

    // If the input number is not divisible by any prime numbers, then it is a prime number
    return 0;
}

int main() {
    int n = 17;
    int primes[10000];

    // Check if the input number is prime or not
    if (is_prime(n, primes)) {
        printf("%d is a prime number.\n", n);
    } else {
        printf("%d is not a prime number.\n", n);
    }

    return 0;
}
```
