            @Override
            public void run() {
                // Generate a random number between 1 and 100
                Random r = new Random();
                int num = r.nextInt(100) + 1;

                // Check if the number is prime
                boolean isPrime = checkIfPrime(num);

                // Print the result to the console
                System.out.println("Number " + num + ": ");
                if (isPrime) {
                    System.out.println("  Prime");
                } else {
                    System.out.println("  Not prime");
                    System.out.print("  Factors: ");
                    for (int i : findFactors(num)) {
                        System.out.print(i + " ");
                    }
                    System.out.println();
                }

                // Sleep the thread for a random amount of time between 1 and 5 seconds
                int sleepTime = r.nextInt(4) + 1;
                Thread.sleep(sleepTime * 1000);
            }
        });

        // Run the thread indefinitely until the user enters 0
        while (true) {
            t.start();

            Scanner sc = new Scanner(System.in);
            System.out.print("Enter a number (0 to terminate): ");
            int input = sc.nextInt();

            if (input == 0) {
                break;
            }
        }

        // Terminate the thread and print "Thread terminated" to the console
        t.interrupt();
        System.out.println("Thread terminated");
    }

    /**
     * Check if a number is prime efficiently without using brute force
     */
    public static boolean checkIfPrime(int num) {
        // Base case: 1 is not prime
        if (num <= 1) return false;

        // Check if the number is divisible by 2 to 10
        for (int i = 2; i < 11; i++) {
            if (num % i == 0) return false;
        }

        // If the number passes all previous tests, it is prime
        return true;
    }

    /**
     * Find the prime factors of a number efficiently without using brute force
     */
    public static int[] findFactors(int num) {
        // Base case: if the number is 1 or negative, there are no prime factors
        if (num <= 0 || num == 1) return new int[0];

        // Initialize an array to store the prime factors
        int[] factors = new int[num];
        int factorCount = 0;

        // Check if the number is divisible by 2
        while (num % 2 == 0) {
            factors[factorCount++] = 2;
            num /= 2;
        }

        // Check if the number is divisible by odd numbers from 3 to the square root of the number
        for (int i = 3; i * i <= num; i += 2) {
            while (num % i == 0) {
                factors[factorCount++] = i;
                num /= i;
            }
        }

        // If the number is not divisible by any odd numbers, it is prime
        if (num > 1) factors[factorCount++] = num;

        return Arrays.copyOf(factors, factorCount);
    }
}

