// Function to add an item to the queue using binary search.
void enqueue(int value) {
  // If the queue is empty, add the new value at the end of the array.
  if (front == -1 && rear == -1) {
    front = 0;
    rear = 0;
    arr[rear] = value;
  } else {
    // Find the index where the new value should be inserted using binary search.
    int low = front, high = rear;
    while (low <= high) {
      int mid = (low + high) / 2;
      if (arr[mid] > value) {
        high = mid - 1;
      } else if (arr[mid] < value) {
        low = mid + 1;
      } else {
        // If the new value is already present in the array, do not add it again.
        return;
      }
    }
    // Shift all elements between low and high to make space for the new value.
    for (int i = rear; i >= high + 1; --i) {
      arr[i] = arr[i - 1];
    }
    // Add the new value at the index found using binary search.
    arr[high + 1] = value;
    ++rear;
  }
}
```
