import re

def find_unique_matches(strings, patterns):
    matches = set()
    for string in strings:
        for pattern in patterns:
            for match in pattern.finditer(string):
                if len(match.group()) > 2 and match.group() not in matches:
                    matches.add(match.group())
    return matches
