                    sub_non_zero_elements.append(key)
                else:
                    zero_elements.append(key)
            non_zero_elements.extend(sub_non_zero_elements)
        elif isinstance(element, set):
            # Move zeros within nested sets
            sub_non_zero_elements = []
            for item in element:
                if not item == 0:
                    sub_non_zero_elements.append(item)
                else:
                    zero_elements.add(item)
            non_zero_elements.extend(sub_non_zero_elements)
        elif isinstance(element, tuple):
            # Move zeros within nested tuples
            sub_non_zero_elements = []
            for item in element:
                if not item == 0:
                    sub_non_zero_elements.append(item)
                else:
                    zero_elements.add(item)
            non_zero_elements.extend(sub_non_zero_elements)
        elif isinstance(element, str):
            # Move zeros within nested strings
            sub_non_zero_elements = []
            for char in element:
                if not char == "0":
                    sub_non_zero_elements.append(char)
                else:
                    zero_elements.add(char)
            non_zero_elements.extend(sub_non_zero_elements)
        elif isinstance(element, float):
            # Move zeros within nested floats
            if not element == 0.0:
                non_zero_elements.append(element)
            else:
                zero_elements.add(element)
        elif hasattr(element, "is_zero"):
            # Move zeros within custom objects
            if not element.is_zero():
                non_zero_elements.append(element)
