function removeConsecutiveDuplicates(str) {
  const n = str.length;
  let prev = null;
  let count = 0;
  let result = "";
  let index = 0;

  for (let i = 0; i < n; i++) {
    const curr = str[i];

    if (curr === prev) {
      count++;
    } else {
      count = 1;
      prev = curr;
    }

    if (count === 1) {
      result += curr;
      index++;
    }
  }

  for (let i = 0; i < n; i++) {
    const char = str[i];

    if (char !== prev) {
      result += char;
      index++;
    }
  }

  return result;
}
```
