```python
import math

def binomial_coefficient(n, k):
    if n < 0 or k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if n % 2 == 0 and k % 2 == 0:
        return binomial_coefficient(n // 2, k // 2) * math.pow(3, n - k)
    elif n % 2 != 0 and k % 2 != 0:
        return binomial_coefficient((n + 1) // 2, (k + 1) // 2) * math.pow(-1, n - k)
    else:
        return 0
