class MinHeap {
    private heap = [];

    /**
     * Creates a new min heap object.
     */
    constructor() {
        this.heap = [];
    }

    /**
     * Inserts a new element into the heap.
     * @param element The element to insert.
     */
    insert(element) {
        // Insert the element at the end of the array
        this.heap.push(element);
        // Bubble up the element to its correct position in the heap
        let index = this.heap.length - 1;
        while (index > 0 && this.compare(this.heap[index], this.heap[Math.floor((index - 1) / 2)])) {
            const parentIndex = Math.floor((index - 1) / 2);
            [this.heap[parentIndex], this.heap[index]] = [this.heap[index], this.heap[parentIndex]];
            index = parentIndex;
        }
    }

    /**
     * Removes the minimum element from the heap and returns it.
     * @returns The removed element, or undefined if the heap is empty.
     */
    removeMin() {
        // Return undefined if the heap is empty
        if (this.heap.length === 0) return undefined;

        // Remove the first element from the array and swap it with the last element
        const removedElement = this.heap[0];
        [this.heap[0], this.heap[this.heap.length - 1]] = [this.heap[this.heap.length - 1], this.heap[0]];
        this.heap.pop();

        // Bubble down the last element to its correct position in the heap
        let index = 0;
        while (2 * index + 1 < this.heap.length) {
            const leftChildIndex = 2 * index + 1;
            const rightChildIndex = 2 * index + 2;
            const smallestChildIndex = this.heap[leftChildIndex] <= this.heap[rightChildIndex] ? leftChildIndex : rightChildIndex;
            if (this.compare(this.heap[smallestChildIndex], this.heap[index])) {
                [this.heap[smallestChildIndex], this.heap[index]] = [this.heap[index], this.heap[smallestChildIndex]];
                index = smallestChildIndex;
            } else {
                break;
            }
        }

        return removedElement;
    }

    /**
     * Returns the minimum element in the heap, or undefined if the heap is empty.
     * @returns The minimum element in the heap, or undefined if the heap is empty.
     */
    getMin() {
        // Return undefined if the heap is empty
        if (this.heap.length === 0) return undefined;

        return this.heap[0];
    }

    /**
     * Returns whether the heap is empty.
     * @returns Whether the heap is empty.
     */
    isEmpty() {
        // Return true if the heap is empty, false otherwise
        return this.heap.length === 0;
    }

    /**
     * Compares two elements in the heap based on their natural order.
     * @param element1 The first element to compare.
     * @param element2 The second element to compare.
     * @returns Whether element1 is less than element2.
     */
    compare(element1, element2) {
        // Return true if element1 is less than element2, false otherwise
        return element1 < element2;
    }
}
