```
// Define the encryption and decryption functions
function encrypt(input, password) {
  // Create a random salt value for this encryption session
  const salt = generateRandomSalt();

  // Derive the key from the password using PBKDF2
  const key = deriveKeyFromPassword(password, salt);

  // Encrypt the input string with AES-GCM
  const ciphertext = aesGcmEncrypt(input, key, salt);

  // Return the encrypted string as a hexadecimal string
  return ciphertext.toString('hex');
}

function decrypt(encryptedInput, password) {
  // Parse the encrypted input from a hexadecimal string to a Buffer object
  const ciphertext = Buffer.from(encryptedInput, 'hex');

  // Derive the key from the password using PBKDF2
  const key = deriveKeyFromPassword(password);

  // Decrypt the input with AES-GCM
  const plaintext = aesGcmDecrypt(ciphertext, key);

  // Return the decrypted string
  return plaintext.toString();
}

// Define the PBKDF2 function for deriving keys from passwords
function deriveKeyFromPassword(password, salt) {
  const kdf = crypto.createPbkdf2('sha512', password, salt, 10000, 64);
  return kdf.deriveKey();
}

// Define the AES-GCM encryption and decryption functions
function aesGcmEncrypt(input, key, salt) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  let encrypted = cipher.update(input);
  encrypted = Buffer.concat([encrypted, cipher.final()]);
  return {
    iv: iv.toString('hex'),
    salt: salt.toString('hex'),
    ciphertext: encrypted.toString('hex')
  };
}

function aesGcmDecrypt(ciphertext, key) {
  const iv = Buffer.from(ciphertext.iv, 'hex');
  const salt = Buffer.from(ciphertext.salt, 'hex');
  const cipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  let decrypted = cipher.update(Buffer.from(ciphertext.ciphertext, 'hex'));
  decrypted = Buffer.concat([decrypted, cipher.final()]);
  return decrypted.toString();
}

// Define the generateRandomSalt function for generating random salt values
function generateRandomSalt() {
  const salt = crypto.randomBytes(32);
  return salt.toString('hex');
}
```
In this example, we define a `encrypt` function that takes an input string and a password as arguments, and returns the encrypted string as a hexadecimal string. The encryption algorithm incorporates a random salt value and a key derived from the password using PBKDF2. The encrypted string is then encrypted with AES-GCM.

We also define a `decrypt` function that takes an encrypted input string, a password, and a random salt value as arguments, and returns the decrypted string. The decryption algorithm derives the key from the password using PBKDF2, and then decrypts the input with AES-GCM.

The `deriveKeyFromPassword` function takes a password and a random salt value as arguments, and returns a derived key using PBKDF2. The `aesGcmEncrypt` function takes an input string, a key, and a random salt value as arguments, and returns the encrypted output as a hexadecimal string. The `aesGcmDecrypt` function takes an encrypted input string, a key, and a random salt value as arguments, and returns the decrypted output.

The `generateRandomSalt` function generates a random salt value using `crypto.randomBytes`, and returns it as a hexadecimal string.

You can use these functions to encrypt and decrypt strings in your application, like this:
```
const password = 'MyPassword';
const input = 'Hello World!';
const encryptedInput = encrypt(input, password);
console.log(encryptedInput); // Outputs the encrypted string as a hexadecimal string

// ...later...

const decryptedInput = decrypt(encryptedInput, password);
console.log(decryptedInput); // Outputs the original input string
```

