                }
            }
        }
    }

    public string GetDirectory()
    {
        return m_argumentsCollection.ContainsKey('d') ? m_argumentsCollection['d'] : string.Empty;
    }

    public string GetPropsFile()
    {
        return m_argumentsCollection.ContainsKey('p') ? m_argumentsCollection['p'] : null;
    }
}
```

