#include <unordered_map>

using namespace std;

// Define a structure to store the data for each country
struct Country {
    string name;
    int population;
};

// Create an unordered map to store the data for all countries
const unordered_map<string, Country> CNTS = {
    {"USA", { "United States of America", 331001870 }},
    {"CHN", { "China", 1405000366 }},
    {"IND", { "India", 1381091245 }}
};

// Define a function to find the population of a country
int getPopulation(const string& c) {
    // Check if the country is in the map
    if (CNTS.find(c) == CNTS.end()) {
        // If not, return 0
        return 0;
    } else {
        // Otherwise, return the population of the country
        return CNTS.at(c).population;
    }
}

// Define a function to print the population of a country
void printPopulation(const string& c) {
    // Check if the country is in the map
    if (CNTS.find(c) == CNTS.end()) {
        // If not, print an error message
        cout << "Error: Country '" << c << "' does not exist." << endl;
    } else {
        // Otherwise, print the population of the country
        cout << "The population of " << c << " is " << getPopulation(c) << " people." << endl;
    }
}

int main() {
    string country;

    // Ask for a country name and call the `printPopulation` function
    cout << "Enter a country name: ";
    cin >> country;
    printPopulation(country);

    return 0;
}
```
