def longest_increasing_subsequence(numbers):
    """Find the longest increasing subsequence in a list of numbers."""
    # Create a dictionary to store the results of previous iterations
    memo = {}

    # Define a function to calculate the length of an increasing subsequence
    def length(i, j):
        if i > j:
            return 0
        elif i == j:
            return 1
        else:
            return max(length(i + 1, j), length(i, j - 1) + 1)

    # Iterate over the numbers and calculate the longest increasing subsequence for each one
    for i in range(len(numbers)):
        memo[i] = length(0, i)

    # Return the maximum value in the dictionary
    return max(memo.values())
