function rotate90(cube) {
  // Create an empty array to store the rotated cube
  const rotatedCube = new Array(cube.length);

  // Loop through each layer of the cube
  for (let i = 0; i < cube.length; i++) {
    // Get the current layer of the cube
    const layer = cube[i];

    // Create an empty array to store the rotated layer
    const rotatedLayer = new Array(layer.length);

    // Loop through each element of the current layer
    for (let j = 0; j < layer.length; j++) {
      // Get the current element of the layer
      const element = layer[j];

      // Calculate the index of the rotated element in the new layer
      let rotatedIndex = cube.length - i - 1;

      // Add the rotated element to the rotated layer
      rotatedLayer[rotatedIndex] = element;
    }

    // Add the rotated layer to the rotated cube
    rotatedCube[i] = rotatedLayer;
  }

  return rotatedCube;
}
```
