```
#include <iostream>
#include <sstream>
#include <iomanip>
#include <cmath>

std::string numberToString(double num) {
    // Check if the number is a hexadecimal integer
    if (num == static_cast<int>(num)) {
        return std::to_string(static_cast<int>(num));
    }

    // Check if the number has decimal places
    double dec = num - static_cast<int>(num);
    if (dec != 0) {
        // Round the number to the nearest integer
        int rounded = std::round(num);
        return std::to_string(rounded);
    }

    // Check if the number is negative
    if (num < 0) {
        return "-" + std::to_string(static_cast<int>(-num));
    }

    // Convert the number to scientific notation if necessary
    int exponent = 0;
    while (num >= 10) {
        num /= 10;
        ++exponent;
    }
    while (num < 1) {
        num *= 10;
        --exponent;
    }
    if (exponent != 0) {
        return std::to_string(static_cast<int>(num)) + "e" + std::to_string(exponent);
    }

    // Convert the number to a string without using any built-in library functions
    std::ostringstream oss;
    oss << std::setprecision(std::numeric_limits<double>::digits10) << num;
    return oss.str();
}
```
