Here is an example of how you could create a dynamic table with three columns and populate it with data fetched from an asynchronous API call using JavaScript:
```
<!DOCTYPE html>
<html>
<head>
	<title>Dynamic Table</title>
	<style>
		table, th, td {
			border: 1px solid black;
		}
	</style>
</head>
<body>
	<h1>Dynamic Table</h1>
	<table id="myTable">
		<thead>
			<tr>
				<th>ID</th>
				<th>Name</th>
				<th>Group</th>
			</tr>
		</thead>
		<tbody id="myTableBody">
			<!-- Dynamic content will be added here -->
		</tbody>
	</table>
	<script>
		// Function to make the API call and populate the table with data
		async function fetchData() {
			try {
				const response = await fetch('https://example.com/api/data');
				const data = await response.json();
				populateTable(data);
			} catch (error) {
				console.error(error);
			}
		}

		// Function to populate the table with data
		function populateTable(data) {
			const tableBody = document.getElementById('myTableBody');
			for (let i = 0; i < data.length; i++) {
				const row = `<tr>
					<td>${data[i].id}</td>
					<td>${data[i].name}</td>
					<td>${data[i].group}</td>
				</tr>`;
				tableBody.innerHTML += row;
			}
		}

		// Function to sort the table by ID or Name columns
		function sortTable() {
			const table = document.getElementById('myTable');
			const tbody = document.getElementById('myTableBody');
			let rows = Array.from(tbody.children);
			rows = rows.sort((a, b) => {
				const idA = a.querySelector('td:first-child').innerHTML;
				const idB = b.querySelector('td:first-child').innerHTML;
				return idA - idB;
			});
			tbody.innerHTML = '';
			rows.forEach(row => {
				tbody.appendChild(row);
			});
		}

		// Call the API and populate the table with data
		fetchData();

		// Add event listeners to sort the table by ID or Name columns
		document.getElementById('myTable').addEventListener('click', function(event) {
			if (event.target.classList.contains('sort-id')) {
				sortTable();
			} else if (event.target.classList.contains('sort-name')) {
				sortTable();
			}
		});
	</script>
</body>
</html>
```
In this example, we first define the structure of the table using HTML and CSS. We then use JavaScript to make an asynchronous API call and populate the table with data fetched from the API. We also add event listeners to allow users to sort the table by ID or Name columns.

The `fetchData()` function makes a GET request to an external API endpoint using the `fetch` function, which returns a promise that resolves with the response data. We then use the `populateTable()` function to populate the table with the data fetched from the API.

To sort the table by ID or Name columns, we add event listeners to the table element that listen for clicks on the ID or Name column headers. When a click is detected, we call the `sortTable()` function, which sorts the rows of the table based on the value of the first cell in each row (the ID or Name).

Note that this example assumes that the API endpoint returns data in the format expected by the `populateTable()` function. If the API endpoint returns different data, you may need to modify the `populateTable()` function accordingly.

