duplicate_count <- function(str) {
  # Initialize an empty list to store the duplicate characters
  dups <- list()

  # Iterate over each character in the string
  for (i in seq_along(str)) {
    # Check if the current character has already been seen before
    if (!is.na(match(str[i], dups))) {
      # If it has, increment its count by 1
      dups[[match(str[i], dups)]] <<- dups[[match(str[i], dups)]] + 1
    } else {
      # Otherwise, add it to the list of unique characters
      dups <- c(dups, str[i])
    }
  }

  # Return a named vector containing the count of each duplicate character found in the string
  return(setNames(dups, names(dups)))
}
```
