// Function to make a GET request to the API
function makeGetRequest(url, params, callback) {
  const options = {
    hostname: url.hostname,
    port: url.port,
    path: url.pathname + '?' + querystring.stringify(params),
    method: 'GET',
    headers: {}
  };

  // Handle rate limiting by checking the X-RateLimit-Remaining header in the response
