    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      callback(null, data);
    });

    // Handle network errors and server errors
    res.on('error', (err) => {
      console.log(err);
      callback(err);
    });
  }).on('error', (err) => {
    console.log(err);
    callback(err);
  });
}

// Function to retrieve data from the API and print it to the console
function retrieveData(url, params, callback) {
  makeGetRequest(url, params, (err, data) => {
    if (err) {
      console.log('Error: ' + err);
      return;
    }

    // Handle pagination by checking the X-Page-Number and X-Total-Pages headers in the response
    const pageNumber = parseInt(res.headers['x-page-number'], 10);
    const totalPages = parseInt(res.headers['x-total-pages'], 10);

    if (pageNumber === totalPages) {
      // If this is the last page, return all available data
      callback(null, data);
    } else {
      // If there are more pages to retrieve, make a new request with the next page number
      const nextPageParams = Object.assign({}, params, { page: pageNumber + 1 });
      retrieveData(url, nextPageParams, (err, data) => {
        if (err) {
          console.log('Error: ' + err);
          return;
        }

        // Combine the current page's data with the previous pages' data and return it
        const combinedData = JSON.parse(data).concat(JSON.parse(res.body));
        callback(null, combinedData);
      });
    }
  });
}

