        fibonacciSequence[1] = 1; // set the second element of the sequence to 1
        for (int i = 2; i < max; i++) { // iterate from the third element up to the maximum value
            fibonacciSequence[i] = generateFibonacciElement(i); // compute each element of the sequence using a recursive approach
        }
    }

    private static int generateFibonacciElement(int n) {
        if (n == 0 || n == 1) return n; // base case: the first two elements of the sequence are 0 and 1
        else return generateFibonacciElement(n - 1) + generateFibonacciElement(n - 2); // recurrence relation: each element is the sum of its predecessors
    }
}
