<?php
function longestCommonSubsequence($str1, $str2) {
  // Get the lengths of the two input strings
  $len1 = strlen($str1);
  $len2 = strlen($str2);

  // Initialize a matrix to store the length of the maximal subsequence
  $matrix = array_fill(0, $len1 + 1, array_fill(0, $len2 + 1, 0));

  // Loop through each position in the two input strings
  for ($i = 1; $i <= $len1; $i++) {
    for ($j = 1; $j <= $len2; $j++) {
      // Check if the current character in both strings is equal
      if ($str1[$i - 1] === $str2[$j - 1]) {
        // If it is, update the length of the maximal subsequence
        $matrix[$i][$j] = $matrix[$i - 1][$j - 1] + 1;
      } else {
        // Otherwise, use the maximum of the previous two values
        $matrix[$i][$j] = max($matrix[$i - 1][$j], $matrix[$i][$j - 1]);
      }
    }
  }

  // Return the length of the maximal subsequence
  return $matrix[$len1][$len2];
}

// Test the function with some input strings
echo longestCommonSubsequence('banana', 'apple') . "\n";   // Output: 0
echo longestCommonSubsequence('banana', 'ananas') . "\n"; // Output: 3
echo longestCommonSubsequence('banana', 'bannana') . "\n"; // Output: 7
```
