      throw new Error('Age must be a positive integer between 1 and 100');
    }
    this._age = value;
  }

  get grade() {
    return this._grade;
  }

  set grade(value) {
    if (typeof value !== 'number' || value < 0 || value > 100) {
      throw new Error('Grade must be a number between 0 and 100');
    }
    this._grade = value;
  }

  get subjects() {
    return this._subjects;
  }

  set subjects(value) {
    if (!Array.isArray(value)) {
      throw new Error('Subjects must be an array of strings');
    }
    for (const subject of value) {
      if (typeof subject !== 'string' || subject.length === 0) {
        throw new Error('Subjects must be non-empty strings');
      }
    }
    this._subjects = value;
  }

  addSubject(subject) {
    if (!this._subjects.includes(subject)) {
      this._subjects.push(subject);
    }
  }

  removeSubject(subject) {
    const index = this._subjects.indexOf(subject);
    if (index !== -1) {
      this._subjects.splice(index, 1);
    }
  }

  getSubjectCount() {
    return this._subjects.length;
  }

  getGreeting() {
    return `Hello, my name is ${this._name} and I am ${this._age} years old.`;
  }

  getAgeCategory() {
    if (this._age < 13) {
      return 'Child';
    } else if (this._age >= 13 && this._age <= 19) {
      return 'Teenager';
    } else {
      return 'Adult';
    }
