        sortedPairs.add(closestPair2);
        sortedPairs.sort((p1, p2) -> Double.compare(p1.getValue(), p2.getValue()));

        // If there are more than one pair with the same shortest distance, return all such pairs
        if (sortedPairs.size() > 1 && closestPair1.getValue() == closestPair2.getValue()) {
            for (int i = 0; i < list.size(); i++) {
                for (int j = i + 1; j < list.size(); j++) {
                    if (list.get(i) == list.get(j)) {
                        sortedPairs.add(new Pair<Double>(list.get(i), list.get(j)));
                    }
                }
            }
        }

        return sortedPairs;
    }

    private static Pair<Double> findClosestPair(List<Double> list) {
        double minDistance = Double.POSITIVE_INFINITY;
        Pair<Double> closestPair = null;

        for (int i = 0; i < list.size(); i++) {
            for (int j = i + 1; j < list.size(); j++) {
                double distance = Math.abs(list.get(i) - list.get(j));
                if (distance < minDistance) {
                    minDistance = distance;
                    closestPair = new Pair<Double>(list.get(i), list.get(j));
                }
            }
        }

        return closestPair;
    }
}
```
