function getCurrentDateTime(timezone) {
  let date = new Date();
  let day = date.toLocaleString('en-US', { weekday: 'long' });
  let month = date.toLocaleString('en-US', { month: 'long' });
  let dayOfMonth = date.getDate();
  let year = date.getFullYear();
  let hours = date.getHours();
  let minutes = date.getMinutes();
  let seconds = date.getSeconds();
  let amPm = 'AM';
  if (hours >= 12) {
    amPm = 'PM';
  }
  if (hours > 12) {
    hours = hours - 12;
  } else if (hours === 0) {
    hours = 12;
  }
  let formattedTime = `${hours}:${minutes}:${seconds} ${amPm}`;
  if (timezone) {
    try {
      date = new Date(date.toLocaleString('en-US', { timeZone: timezone }));
      day = date.toLocaleString('en-US', { weekday: 'long' });
      month = date.toLocaleString('en-US', { month: 'long' });
      dayOfMonth = date.getDate();
      year = date.getFullYear();
    } catch (err) {
      return `Error: Invalid timezone provided (${timezone}).`;
    }
  }
  return `${day}, ${month} ${dayOfMonth}, ${year} ${formattedTime}`;
}

// Usage examples:
console.log(getCurrentDateTime()); // Output: Wednesday, November 20, 2019 10:30 AM
console.log(getCurrentDateTime('UTC')); // Output: Wednesday, November 20, 2019 10:30 AM (UTC)
console.log(getCurrentDateTime('America/New_York')); // Output: Wednesday, November 20, 2019 5:30 PM (America/New_York)
console.log(getCurrentDateTime('Invalid Timezone')); // Output: Error: Invalid timezone provided (Invalid Timezone).

