#include <iostream>

using namespace std;

void findLargestAndSmallest(int arr[], int size) {
  // Initialize variables to store the largest and smallest values
  int largest = INT_MIN, smallest = INT_MAX;

  // Loop through the array and compare each element to the current largest and smallest values
  for (int i = 0; i < size; i++) {
    if (arr[i] > largest) {
      largest = arr[i];
    }
    if (arr[i] < smallest) {
      smallest = arr[i];
    }
  }

  // Print the largest and smallest values to the console
  cout << "Largest: " << largest << endl;
  cout << "Smallest: " << smallest << endl;
}
