import numpy as np

def get_unique_elements(my_list):
    # Get a list of unique elements from a list
    return list(set(my_list))

def get_duplicate_elements(my_list):
    # Get a list of duplicate elements from a list
    unique_elements = get_unique_elements(my_list)
    duplicate_elements = []
    for element in my_list:
        if my_list.count(element) > 1 and element not in duplicate_elements:
            duplicate_elements.append(element)
    return duplicate_elements

def get_most_frequent_element(my_list):
    # Get the most frequent element from a list
    unique_elements = get_unique_elements(my_list)
    counts = {}
    for element in unique_elements:
        counts[element] = my_list.count(element)
    return max(counts, key=counts.get)

def get_least_frequent_element(my_list):
    # Get the least frequent element from a list
    unique_elements = get_unique_elements(my_list)
    counts = {}
    for element in unique_elements:
        counts[element] = my_list.count(element)
    return min(counts, key=counts.get)

def get_unique_elements_sorted(my_list):
    # Get a list of unique elements from a list sorted in alphabetical order
    return sorted(list(set(my_list)))

def get_duplicate_elements_sorted(my_list):
    # Get a list of duplicate elements from a list sorted in alphabetical order
    unique_elements = get_unique_elements(my_list)
    duplicate_elements = []
    for element in my_list:
        if my_list.count(element) > 1 and element not in duplicate_elements:
            duplicate_elements.append(element)
    return sorted(duplicate_elements)

def get_most_frequent_element_index(my_list):
    # Get the index of the most frequent element from a list
    unique_elements = get_unique_elements(my_list)
    counts = {}
    for i, element in enumerate(unique_elements):
        if element not in counts:
            counts[element] = [i]
        else:
            counts[element].append(i)
    max_count = max([len(v) for v in counts.values()])
    most_frequent_element = None
    most_frequent_index = -1
    for k, v in counts.items():
        if len(v) == max_count and (most_frequent_element is None or my_list.count(k) > my_list.count(most_frequent_element)):
            most_frequent_element = k
            most_frequent_index = v[0]
    return most_frequent_index

def get_least_frequent_element_index(my_list):
    # Get the index of the least frequent element from a list
    unique_elements = get_unique_elements(my_list)
    counts = {}
    for i, element in enumerate(unique_elements):
        if element not in counts:
            counts[element] = [i]
        else:
            counts[element].append(i)
    min_count = min([len(v) for v in counts.values()])
    least_frequent_element = None
    least_frequent_index = -1
    for k, v in counts.items():
        if len(v) == min_count and (least_frequent_element is None or my_list.count(k) < my_list.count(least_frequent_element)):
            least_frequent_element = k
            least_frequent_index = v[0]
    return least_frequent_index

def get_unique_elements_sorted_by_count(my_list):
    # Get a list of unique elements from a list sorted by count in descending order
    unique_elements = get_unique_elements(my_list)
    counts = {}
    for element in unique_elements:
        counts[element] = my_list.count(element)
    return sorted(unique_elements, key=lambda x: counts[x], reverse=True)

def get_duplicate_elements_sorted_by_count(my_list):
    # Get a list of duplicate elements from a list sorted by count in descending order
    unique_elements = get_unique_elements(my_list)
    counts = {}
    for element in unique_elements:
        counts[element] = my_list.count(element)
    return sorted(get_duplicate_elements(my_list), key=lambda x: counts[x], reverse=True)

Here is an example of how you can create an HTML page that displays the contents of a given URL using JavaScript:
```
<!DOCTYPE html>
<html>
<head>
  <title>Display URL Contents</title>
  <script>
    // Create a new XMLHttpRequest object
    var xhr = new XMLHttpRequest();

    // Set the request method and url
    xhr.open('GET', 'https://www.example.com');

    // Set the response type to text
    xhr.responseType = 'text';

    // Define a function to be called when the request completes
    xhr.onload = function() {
      if (xhr.status === 200) {
        // Display the contents of the URL in the HTML page
        document.getElementById('content').innerHTML = xhr.responseText;
      } else {
        console.log('Error: ' + xhr.status);
      }
    };

    // Send the request
    xhr.send();
  </script>
</head>
<body>
  <div id="content"></div>
</body>
```
This HTML page uses an XMLHttpRequest object to send a GET request to the URL specified in the `xhr.open()` method, and then displays the contents of the URL in the HTML page using the `innerHTML` property of a `<div>` element with the ID "content". The `responseType` property is set to `'text'` to indicate that the response should be treated as plain text.

You can also use fetch API which is a simpler way to make HTTP requests and handle responses. Here's an example using fetch API:
```
<!DOCTYPE html>
<html>
<head>
  <title>Display URL Contents</title>
</head>
<body>
  <div id="content"></div>

  <script>
    // Create a new fetch request
    fetch('https://www.example.com')
      .then(response => response.text())
      .then(data => {
        document.getElementById('content').innerHTML = data;
      })
      .catch(error => console.log('Error:', error));
  </script>
</body>
```
This HTML page uses the `fetch()` function to send a GET request to the URL specified in the `fetch()` method, and then displays the contents of the URL in the HTML page using the `innerHTML` property of a `<div>` element with the ID "content". The `text()` method is used to specify that the response should be treated as plain text.

