from typing import List, Tuple, Dict

def factorize(n: int) -> Tuple[List[int], Dict[int, int]]:
    """Return sorted list of prime factors for a given integer and a dictionary with prime factors and their count in the factorization.

    The factors should be listed according to their frequency in the factorization. 
    Input number (2 ≤ n ≤ 10^6) must equal the product of all factors.

    >>> factorize(8)
    ([2, 2, 2], {2: 3})

    >>> factorize(25)
    ([5, 5], {5: 2})

    >>> factorize(70)
    ([2, 5, 7], {2: 1, 5: 1, 7: 1})
    """

    if n < 2 or n > 1000000:
        raise ValueError("n must be between 2 and 1000000")

    factors = []
    factor_counts = {}

    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            factors.append(i)
            factor_counts[i] = factor_counts.get(i, 0) + 1
            while n % i == 0:
                n //= i
    if n > 1:
        factors.append(n)
        factor_counts[n] = factor_counts.get(n, 0) + 1

    return (sorted(factors), factor_counts)

