function findDistinctFibonacciElements(arr) {
  // Create an empty array to store the distinct elements
  const distinctElements = [];

  // Iterate over the input array and check if each element is distinct
  for (let i = 0; i < arr.length; i++) {
    const currentElement = arr[i];

    // Check if the current element is distinct by comparing it to all the previous elements
    let isDistinct = true;
    for (let j = 0; j < i; j++) {
      if (currentElement === arr[j]) {
        isDistinct = false;
        break;
      }
    }

    // If the current element is distinct, add it to the list of distinct elements
    if (isDistinct) {
      distinctElements.push(currentElement);
    }
  }

  return distinctElements;
}

