    }

    // Update historical graph
    updateGraph(sortedData);
}

// Filter data based on selected continents
function filterData(data, asia, africa, americas, europe) {
    const filteredData = [];
    for (let country of data) {
        if (asia && country.continent === 'Asia') {
            filteredData.push(country);
        } else if (africa && country.continent === 'Africa') {
            filteredData.push(country);
        } else if (americas && country.continent === 'Americas') {
            filteredData.push(country);
        } else if (europe && country.continent === 'Europe') {
            filteredData.push(country);
        }
    }
    return filteredData;
}

// Sort data based on selected sorting option
function sortData(data, sortBy) {
    const sortedData = [...data];
    if (sortBy === 'population') {
        sortedData.sort((a, b) => a.population - b.population);
    } else if (sortBy === 'name') {
        sortedData.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sortBy === 'continent') {
        sortedData.sort((a, b) => a.continent.localeCompare(b.continent));
    }
    return sortedData;
}

// Update historical graph with new data
function updateGraph(data) {
    // Create chart instance
    const ctx = document.getElementById('chart').getContext('2d');
    const myChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: data.map(country => country.name),
            datasets: [{
                label: 'Population',
                data: data.map(country => country.population),
                borderColor: 'rgb(255, 99, 132)',
                backgroundColor: 'rgba(255, 99, 132, 0.2)'
            }]
        },
        options: {
            scales: {
                yAxes: [{
                    ticks: {
                        beginAtZero: true
                    }
                }]
            }
        }
    });
}
```
